const i=JSON.parse('{"work":{"id":"wei-liao-zi","schoolId":"military","title":"《尉繚子》","genreStrategy":"parallel","sourceNote":"版本來源自《武經七書》本《尉繚子》二十四篇校勘附記。","chapterIds":["wei-liao-zi_ch-1","wei-liao-zi_ch-2","wei-liao-zi_ch-3","wei-liao-zi_ch-4","wei-liao-zi_ch-5"],"totalChars":3450},"chapters":[{"id":"wei-liao-zi_ch-1","workId":"wei-liao-zi","order":1,"title":"天官","difficulty":4,"estimatedMinutes":10,"passageIds":["wei-liao-zi_ch-1_p-1","wei-liao-zi_ch-1_p-2","wei-liao-zi_ch-1_p-3","wei-liao-zi_ch-1_p-4","wei-liao-zi_ch-1_p-5"],"tags":[]},{"id":"wei-liao-zi_ch-2","workId":"wei-liao-zi","order":2,"title":"兵談","difficulty":4,"estimatedMinutes":10,"passageIds":["wei-liao-zi_ch-2_p-1","wei-liao-zi_ch-2_p-2","wei-liao-zi_ch-2_p-3","wei-liao-zi_ch-2_p-4","wei-liao-zi_ch-2_p-5"],"tags":[]},{"id":"wei-liao-zi_ch-3","workId":"wei-liao-zi","order":3,"title":"制談","difficulty":4,"estimatedMinutes":10,"passageIds":["wei-liao-zi_ch-3_p-1","wei-liao-zi_ch-3_p-2","wei-liao-zi_ch-3_p-3","wei-liao-zi_ch-3_p-4","wei-liao-zi_ch-3_p-5","wei-liao-zi_ch-3_p-6","wei-liao-zi_ch-3_p-7","wei-liao-zi_ch-3_p-8","wei-liao-zi_ch-3_p-9","wei-liao-zi_ch-3_p-10","wei-liao-zi_ch-3_p-11","wei-liao-zi_ch-3_p-12"],"tags":[]},{"id":"wei-liao-zi_ch-4","workId":"wei-liao-zi","order":4,"title":"戰威","difficulty":4,"estimatedMinutes":10,"passageIds":["wei-liao-zi_ch-4_p-1","wei-liao-zi_ch-4_p-2","wei-liao-zi_ch-4_p-3","wei-liao-zi_ch-4_p-4","wei-liao-zi_ch-4_p-5","wei-liao-zi_ch-4_p-6","wei-liao-zi_ch-4_p-7","wei-liao-zi_ch-4_p-8","wei-liao-zi_ch-4_p-9","wei-liao-zi_ch-4_p-10","wei-liao-zi_ch-4_p-11","wei-liao-zi_ch-4_p-12","wei-liao-zi_ch-4_p-13","wei-liao-zi_ch-4_p-14","wei-liao-zi_ch-4_p-15"],"tags":[]},{"id":"wei-liao-zi_ch-5","workId":"wei-liao-zi","order":5,"title":"攻權","difficulty":4,"estimatedMinutes":10,"passageIds":["wei-liao-zi_ch-5_p-1","wei-liao-zi_ch-5_p-2","wei-liao-zi_ch-5_p-3","wei-liao-zi_ch-5_p-4","wei-liao-zi_ch-5_p-5","wei-liao-zi_ch-5_p-6","wei-liao-zi_ch-5_p-7","wei-liao-zi_ch-5_p-8","wei-liao-zi_ch-5_p-9","wei-liao-zi_ch-5_p-10","wei-liao-zi_ch-5_p-11"],"tags":[]}],"passages":[{"id":"wei-liao-zi_ch-1_p-1","chapterId":"wei-liao-zi_ch-1","order":1,"canonicalText":"梁惠王問尉繚子曰：「黃帝刑德，可以百勝，有之乎？」尉繚子對曰：「刑以伐之，德以守之，非所謂天官時日陰陽向背也。黃帝者，人事而已矣。何者？今高城深池，宿儲不備，卒雖百萬，何以能守？」","sentenceIds":["wei-liao-zi_ch-1_p-1_s-1","wei-liao-zi_ch-1_p-1_s-2","wei-liao-zi_ch-1_p-1_s-3","wei-liao-zi_ch-1_p-1_s-4","wei-liao-zi_ch-1_p-1_s-5","wei-liao-zi_ch-1_p-1_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"魏惠王（梁惠王）向兵學大師尉繚子詢問道：相傳黃帝創立的陰陽五行刑德時日之法，可以百戰百勝，真有這回事嗎？尉繚子回答說：所謂刑是指用軍事武力討伐暴逆，所謂德是指用政治仁德守衛社稷，根本不是指占星望氣（天官）、挑選黃道吉日（時日）以及迷信陰陽星象向背那一套！黃帝之所以百戰百勝，完全在於人為的政治與軍事準備（人事而已矣）！為什麼這樣說呢？如今縱然有高聳的城牆、深邃的護城河，如果平時不儲備充足的糧草物資，縱然有百萬大軍守城，又憑什麼能夠守得住呢？","analysis":"【題解與非天官而重人事】本段為《尉繚子・天官》開篇，尉繚子以唯物主義戰略理性破除上古「天官時日、陰陽刑德」迷信，確立「黃帝者人事而已矣」的科學戰爭哲學。\\n【詞義訓詁】「梁惠王」：戰國魏惠王遷都大梁，故稱梁惠王；「刑德」：古代陰陽家吉凶時日星象之術；「天官」：天文占星之官與星象吉凶說；「人事而已」：人為主觀能動性、制度與物資準備。\\n【軍事唯物主義】尉繚子繼承孫子「不可取於鬼神」之思想，指出戰爭勝負完全取決於政治修明、後勤儲備與戰術指揮，徹底掃除鬼神迷信對戰略決策之幹擾。"}},{"id":"wei-liao-zi_ch-1_p-2","chapterId":"wei-liao-zi_ch-1","order":2,"canonicalText":"「今有城，東西攻不能取；南北攻不能取；四方豈無順時乘之者耶？然不能取者，城高池深，兵器備具，財穀多，豪傑齊心也。若城下池涸，糧盡兵疲，雖得良辰吉日，不能勝也。」","sentenceIds":["wei-liao-zi_ch-1_p-2_s-1","wei-liao-zi_ch-1_p-2_s-2","wei-liao-zi_ch-1_p-2_s-3","wei-liao-zi_ch-1_p-2_s-4","wei-liao-zi_ch-1_p-2_s-5","wei-liao-zi_ch-1_p-2_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於今有城的情境，應當採取相應的具體對策，對於東西攻不的情境，應當採取相應的具體對策，對於南北攻不的情境，應當採取相應的具體對策，對於四方豈無的情境，應當採取相應的具體對策，對於然不能取的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《尉繚子》〈天官〉第 2 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「今有城東西攻不能取南北攻不能取四方豈無順……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「今」、「有」、「城」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-1_p-2）。"}},{"id":"wei-liao-zi_ch-1_p-3","chapterId":"wei-liao-zi_ch-1","order":3,"canonicalText":"「按天官曰：『背水陣為絕地，向阪陣為廢軍。』武王伐紂，背濟水向山阪而陣，以二萬二千五百人，擊紂之億萬之眾，而破商紂。豈紂不得吉日，而武王反得兇時乎？非也，政審而兵精也。」","sentenceIds":["wei-liao-zi_ch-1_p-3_s-1","wei-liao-zi_ch-1_p-3_s-2","wei-liao-zi_ch-1_p-3_s-3","wei-liao-zi_ch-1_p-3_s-4","wei-liao-zi_ch-1_p-3_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"按照迷信的天官星佔風水術說：背對江河列陣是自絕退路的絕地，面向陡峭山坡列陣是自廢武功的殘軍。然而當年周武王起兵伐紂時，正是背對著濟水、面向著山阪排兵布陣，僅僅憑藉精銳兵力兩萬二千五百人，直接迎擊商紂王的百萬億萬大軍，卻一舉徹底消滅擊破了商紂王！難道是商紂王沒有挑選良辰吉日，而周武王反而故意挑選凶煞時辰嗎？絕非如此！根本原因在於周武王政治清明審度而軍隊訓練精良！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈天官〉第 3 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「按天官曰背水陣為絕地向阪陣為廢軍武王伐紂背濟……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「按」、「天」、「官」、「背」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-1_p-4","chapterId":"wei-liao-zi_ch-1","order":4,"canonicalText":"「楚將公子心與齊人戰，時有彗星出，柄在齊。柄所在勝，不可擊。公子心曰：『彗星何知？以彗鬥者，固當倒而擊之。』明日與齊戰，大破齊軍。故勝在人，不在天也。」","sentenceIds":["wei-liao-zi_ch-1_p-4_s-1","wei-liao-zi_ch-1_p-4_s-2","wei-liao-zi_ch-1_p-4_s-3","wei-liao-zi_ch-1_p-4_s-4","wei-liao-zi_ch-1_p-4_s-5","wei-liao-zi_ch-1_p-4_s-6","wei-liao-zi_ch-1_p-4_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"楚國名將公子心率軍同齊軍大戰，交戰前夕夜空中突然出現彗星天象，彗星的掃帚柄正指向齊國陣營方向。當時的星佔官皆認為：彗星柄所指的方向必定獲勝，不可主動進攻。公子心毅然說道：天上的彗星懂什麼人事打仗？若真要用彗星掃帚打仗，正應當把掃帚柄倒轉過來猛擊敵人！第二天公子心揮軍果斷與齊軍交戰，大破齊國大軍！所以戰爭的勝利完全取決於人為的奮鬥智勇，絕不取決於虛妄的天象！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈天官〉第 4 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「楚將公子心與齊人戰時有彗星出柄在齊柄所在勝不……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「楚」、「將」、「公」、「子」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-1_p-5","chapterId":"wei-liao-zi_ch-1","order":5,"canonicalText":"「黃帝曰：『先神先鬼，先稽我智。』謂之天官人事而已。」","sentenceIds":["wei-liao-zi_ch-1_p-5_s-1","wei-liao-zi_ch-1_p-5_s-2","wei-liao-zi_ch-1_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"黃帝曾留下至理名言：在祈求神明、占卜鬼神之前，必須首先反求考察我們自身的智慧與人事準備！古人所謂的天官天時，本質上不過是人為努力與客觀規律（人事）的代名詞罷了！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈天官〉第 5 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「黃帝曰先神先鬼先稽我智謂之天官人事而已……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「黃」、「帝」、「先」、「神」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-2_p-1","chapterId":"wei-liao-zi_ch-2","order":1,"canonicalText":"量土地肥墝而立邑，建城稱地，以城稱人，以人稱粟。三相稱，則內可以固守，外可以戰勝。戰勝於外，備主於內，勝備相應，霸王之業成矣。","sentenceIds":["wei-liao-zi_ch-2_p-1_s-1","wei-liao-zi_ch-2_p-1_s-2","wei-liao-zi_ch-2_p-1_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"衡量土地的肥沃與貧瘠（肥墝）來合理建立城邑聚落，修築的城池規模要與土地的承載力相稱，城池的大小要與居住的人口數量相稱，人口的規模要與儲備生產的糧食（粟）相稱！土地、人口與糧食三者完全平衡相稱，那麼對內就可以固若金湯地防守，對外就可以所向披靡地戰勝！在外部戰勝強敵，在內部充實戰略儲備，外戰勝利與內部充足準備互為呼應，統一天下的霸王大業便水到渠成了！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈兵談〉第 6 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「量土地肥墝而立邑建城稱地以城稱人以人稱粟……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「量」、「土」、「地」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-2_p-1）。"}},{"id":"wei-liao-zi_ch-2_p-2","chapterId":"wei-liao-zi_ch-2","order":2,"canonicalText":"治兵者，若祕於地，若邃於天，生於無，故關之。大不窕，小不恢，明乎禁舍開塞，民流者親之。地不闢，田不荒，兵強而國富，此治兵之本也。","sentenceIds":["wei-liao-zi_ch-2_p-2_s-1","wei-liao-zi_ch-2_p-2_s-2","wei-liao-zi_ch-2_p-2_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"治理指揮軍隊的將帥，其戰略意圖應當如同深藏在地底一樣隱祕，其軍事智謀應當如同高懸在九天一樣深邃（若祕於地，若邃於天），神機妙算如同無中生有般不可捉摸！規模宏大而不顯得空虛疏漏（大不窕），編制精巧而不顯得狹隘擁擠（小不恢）；深明何者當禁止、何者當準許、何者當開放、何者當堵塞之政策法度，流離失所的流民主動親近安撫他們。土地得到充分開墾，田園絕不荒廢拋荒，軍隊自然強大而國家自然富庶，這才是治理整頓軍隊的根本源頭！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈兵談〉第 7 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「治兵者若祕於地若邃於天生於無故關之大不窕……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「治」、「兵」、「者」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-2_p-2）。"}},{"id":"wei-liao-zi_ch-2_p-3","chapterId":"wei-liao-zi_ch-2","order":3,"canonicalText":"兵起，非可以忿也，見勝則興，不見勝則止。患在百里之內，不起一日之師；患在千里之內，不起一月之師。必先料敵，審知其情，勝乃可圖也。","sentenceIds":["wei-liao-zi_ch-2_p-3_s-1","wei-liao-zi_ch-2_p-3_s-2","wei-liao-zi_ch-2_p-3_s-3","wei-liao-zi_ch-2_p-3_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"發動軍隊戰爭，絕不可憑藉一時的憤怒衝動（非可以忿也），只有確切看見必勝把握才果斷興兵，看不見勝利把握就堅決按兵不動！禍患如果威脅在方圓百里之內，切莫發動需要消耗一日以上的大軍；禍患如果威脅在千里之外，切莫輕易發動需要遠徵一月以上的大軍！必須首先仔細審度敵情，透徹了解敵人的虛實動向，然後勝利才可以胸有成竹地謀取！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈兵談〉第 8 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「兵起非可以忿也見勝則興不見勝則止患在百里之內……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「兵」、「起」、「非」、「可」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-2_p-4","chapterId":"wei-liao-zi_ch-2","order":4,"canonicalText":"將者，上不制於天，下不制於地，中不制於人，寬不可激而怒，清不可事以財。夫心狂、目盲、耳聾，不可為將也。將明則三軍附，將威則三軍整。","sentenceIds":["wei-liao-zi_ch-2_p-4_s-1","wei-liao-zi_ch-2_p-4_s-2","wei-liao-zi_ch-2_p-4_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"身為統帥大將，對上不受虛妄天象星佔的牽制束縛，對下不受艱險地理環境的恐嚇阻礙，對中不受朝廷奸佞與敵方流言的幹擾左右！大將心胸寬廣絕不可被敵人的挑釁言語激怒，品格清廉剛正絕不可用金錢財寶去賄賂收買！凡是內心狂妄躁動、雙目盲目不見大勢、雙耳失聰不聽諫言的人，絕對不可任命為三軍大將！將帥英明洞察則三軍將士由衷歸附，將帥威嚴肅穆則全軍陣容整肅齊整！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈兵談〉第 9 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「將者上不制於天下不制於地中不制於人寬不可……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「將」、「者」、「上」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-2_p-4）。"}},{"id":"wei-liao-zi_ch-2_p-5","chapterId":"wei-liao-zi_ch-2","order":5,"canonicalText":"兵之所及，羊腸亦勝，鋸齒亦勝，緣山亦勝，入谷亦勝，方亦勝，員亦勝。重者如山、如林、如江、如海，不可摧也。此之謂全勝之師。","sentenceIds":["wei-liao-zi_ch-2_p-5_s-1","wei-liao-zi_ch-2_p-5_s-2","wei-liao-zi_ch-2_p-5_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"精銳大軍所向披靡之處，在羊腸小道作戰能奪取勝利，在鋸齒狀險要地形作戰能奪取勝利，沿著險峻山脊行軍能奪取勝利，深入幽深峽谷作戰能奪取勝利，擺出方陣能獲勝，擺出圓陣亦能獲勝！全軍厚重威嚴之勢，堅固如同巍峨泰山，整肅如同森嚴密林，奔湧如同滔滔長江，深沉如同浩瀚大海，無論遭遇任何強敵都不可摧毀！這就稱之為所向披靡的全勝之師！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈兵談〉第 10 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「兵之所及羊腸亦勝鋸齒亦勝緣山亦勝入谷亦勝方亦……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「兵」、「所」、「及」、「羊」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-3_p-1","chapterId":"wei-liao-zi_ch-3","order":1,"canonicalText":"凡兵，制必先定，制先定則士不亂，士不亂則形乃明。金鼓所指，則百人盡鬥。陷行亂陣，則千人盡鬥。斬將搴旗，則萬人盡鬥。此制兵之法也。","sentenceIds":["wei-liao-zi_ch-3_p-1_s-1","wei-liao-zi_ch-3_p-1_s-2","wei-liao-zi_ch-3_p-1_s-3","wei-liao-zi_ch-3_p-1_s-4","wei-liao-zi_ch-3_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於黃帝曰的情境，應當採取相應的具體對策，對於先神先鬼的情境，應當採取相應的具體對策，對於先稽我智的情境，應當採取相應的具體對策，治理國家應以安撫民眾為根本。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《尉繚子》〈制談〉第 11 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「凡兵制必先定制先定則士不亂士不亂則形乃明……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「凡」、「兵」、「制」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-3_p-1）。"}},{"id":"wei-liao-zi_ch-3_p-2","chapterId":"wei-liao-zi_ch-3","order":2,"canonicalText":"古者，士有什伍，車有偏列，鼓鳴旂麾，先登者未嘗非多力國士也，先死者亦未嘗非多力國士也。故賞其勇，罰其怯，明其分，使人皆知所趨舍。","sentenceIds":["wei-liao-zi_ch-3_p-2_s-1","wei-liao-zi_ch-3_p-2_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於量土地肥的情境，應當採取相應的具體對策，對於建城稱地的情境，應當採取相應的具體對策，治理國家應以安撫民眾為根本，對於三相稱的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《尉繚子》〈制談〉第 12 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「古者士有什伍車有偏列鼓鳴旂麾先登者未嘗非……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「古」、「者」、「士」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-3_p-2）。"}},{"id":"wei-liao-zi_ch-3_p-3","chapterId":"wei-liao-zi_ch-3","order":3,"canonicalText":"損敵一人，而損我百人，此資敵而傷甚焉，世將不能禁。徵役分軍而逃歸，或臨戰自北，則逃傷甚焉，故立法以禁之。","sentenceIds":["wei-liao-zi_ch-3_p-3_s-1","wei-liao-zi_ch-3_p-3_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"如果消滅敵人一名士兵，卻要損失我們自己一百名士兵，這簡直是變相在資助敵人，而且我們自己受到的傷害太大了，一般的將領往往無法禁止這種無謂的消耗。如果是徵召來的士兵離開軍隊逃跑回家，或者在臨陣作戰時自己向後潰退逃跑，這種逃跑帶來的危害甚至比前面說的戰損還要嚴重。因此，必須制定嚴厲的軍法來禁止這些行為。","analysis":"【訓詁與名物】「損」在此指殺傷、消耗。「資」是資助、幫助。「世將」指世俗、一般的將領。「徵役」指徵召來的士兵。「分軍」指脫離軍隊。「自北」的「北」是背對敵人逃跑，指敗退、潰逃。\\n【章法與結構】本段以對比和層遞的手法來論述軍法的必要性。首先提出一種極端不划算的戰鬥交換比（損敵一而損我百），指出這是「傷甚」且一般將領難以控制的現象；接著筆鋒一轉，指出「逃亡」與「臨陣退縮」對軍隊的危害，甚至比這種極端的戰損還要可怕（逃傷甚焉）；最後得出結論，點出軍法存在的根本目的（故立法以禁之），邏輯十分嚴密。\\n【思想與義理】此段反映了《尉繚子》在軍事管理上的殘酷現實主義與法治思想。兵家認為，戰爭是國力的消耗，極度不對等的戰損比已經是兵家大忌（資敵）；然而，軍隊內部紀律的崩壞（逃亡與怯戰），更是會直接導致整個軍事體系的瓦解，其破壞力遠大於敵人的殺傷。因此，作者強調不能依賴將領個人的威望或道德勸說（世將不能禁），必須仰賴嚴酷且客觀的「軍法」，用最高的強制力來確保軍隊的凝聚力與戰鬥意志。"}},{"id":"wei-liao-zi_ch-3_p-4","chapterId":"wei-liao-zi_ch-3","order":4,"canonicalText":"民非樂死而惡生也，號令明，法制審，故能使之前。明賞於前，決罰於後，是以發能中利，動則有功。","sentenceIds":["wei-liao-zi_ch-3_p-4_s-1","wei-liao-zi_ch-3_p-4_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"天下百姓與士卒絕非天生喜愛死亡而厭惡生存（民非樂死而惡生），只因為軍隊號令明確、法制嚴密審明，所以才能使他們在戰場上奮勇向前！將明確豐厚的賞賜展示在戰士眼前，將堅決果斷的軍法死刑懸在部隊身後，所以部隊一經出發就能命中目標奪取利益，一經調動就能建立卓越戰功！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈制談〉第 14 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「民非樂死而惡生也號令明法制審故能使之前明賞於……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「民」、「非」、「樂」、「死」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-3_p-5","chapterId":"wei-liao-zi_ch-3","order":5,"canonicalText":"令百人一卒，千人一司馬，萬人一將，以少誅眾，以弱誅強。試聽臣言，其術足使三軍之眾，誅一人無赦，而萬人莫敢犯也。","sentenceIds":["wei-liao-zi_ch-3_p-5_s-1","wei-liao-zi_ch-3_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"讓一百人編為一卒（設一長官），一千人設一司馬，一萬人設一將軍，這樣就能透過層層節制，用少數的軍官來控制、懲處多數的士兵，用看似弱勢的管理層來鎮壓強悍的兵卒。請試著聽從我的建議，這種管理方法足以讓三軍的廣大將士，在軍法懲處任何一個犯錯的人時，沒有任何人敢求情赦免，同時上萬名士兵也沒有任何一個人敢觸犯軍規。","analysis":"【訓詁與名物】「卒」在此指軍隊的編制單位，通常百人為一卒。「司馬」是古代軍隊中的中高級將領。「將」為軍隊統帥。「誅」指懲處、殺戮。「術」指管理的方法與制度。「無赦」指絕不寬貸。\\n【章法與結構】本段重點在闡述軍隊的編制與軍法的威力。前半句描述了軍隊中從下到上（百人、千人、萬人）的科層編制體系，並點出這種金字塔結構的核心運作邏輯（以少誅眾，以弱誅強）；後半句則以強烈的自信（試聽臣言），描繪了這套制度運作至極致時的完美狀態：軍法如山，萬人震懾。\\n【思想與義理】這段話是古代軍事組織學與法家科層管理思想的完美結合。作者指出，統帥之所以能夠控制龐大且強悍的軍隊，並不是靠他個人的體力或武力，而是依靠嚴密的組織編制（層層節制）與絕對冷酷的軍法。透過這種金字塔狀的權力結構，少數的管理階層（將、司馬）就能有效地約束多數的士兵（以少誅眾）。當軍法執行到「誅一人無赦」的絕對客觀與嚴厲時，就能產生巨大的心理威懾力，達到「萬人莫敢犯」的終極紀律要求。"}},{"id":"wei-liao-zi_ch-3_p-6","chapterId":"wei-liao-zi_ch-3","order":6,"canonicalText":"一賊仗劍擊於市，萬人無不避之者，臣謂：『非一人之獨勇，萬人皆不肖也』。何則？『必死與必生，形不相接也。』故治軍者，在使士卒致必死之志也。","sentenceIds":["wei-liao-zi_ch-3_p-6_s-1","wei-liao-zi_ch-3_p-6_s-2","wei-liao-zi_ch-3_p-6_s-3","wei-liao-zi_ch-3_p-6_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"一個亡命之徒手持利劍在繁華市集上瘋狂砍殺，成千上萬的市民百姓沒有一個不慌忙退避逃跑的；臣認為：這絕非那個亡命之徒一個人特別英勇神武，也絕非那一萬名百姓全都是怯懦無能之輩！這是為什麼呢？因為抱著必死決心的人，與只想苟全性命的人，兩者在生死意志的對決態勢上根本無法對接抗衡！所以善於治理指揮軍隊的統帥，最根本的在於激發全體士卒抱定視死如歸的必死之志！","analysis":"【題解與一賊仗劍市井之喻與必死之志】本段為中國古代心理戰與戰鬥意志論之千古名喻——尉繚子以「一賊持劍萬人避」剖析「必死心態」對「求生心態」的絕對壓倒性優勢！\\n【詞義訓詁】「一賊仗劍於市」：亡命之徒持劍於市集；「必死與必生形不相接」：抱必死決心者具有不可阻擋之精神威懾力；「致必死之志」：培育視死如歸之死士精神。\\n【戰鬥意志之壓倒性】在生死博弈中，決心死戰的一方具有壓倒性的心理威懾。軍隊一旦人人具備必死之心，其戰鬥力將呈幾何級數爆發。"}},{"id":"wei-liao-zi_ch-3_p-7","chapterId":"wei-liao-zi_ch-3","order":7,"canonicalText":"有提九萬之眾，而天下莫能當者，誰？曰：『桓公也。』有提七萬之眾，而天下莫敢當者，誰？曰：『吳起也。』有提三萬之眾，而天下莫敢當者，誰？曰：『武王也。』兵在精而不在多也。","sentenceIds":["wei-liao-zi_ch-3_p-7_s-1","wei-liao-zi_ch-3_p-7_s-2","wei-liao-zi_ch-3_p-7_s-3","wei-liao-zi_ch-3_p-7_s-4","wei-liao-zi_ch-3_p-7_s-5","wei-liao-zi_ch-3_p-7_s-6","wei-liao-zi_ch-3_p-7_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"手握統率九萬精兵，而全天下沒有任何諸侯強敵能夠抵擋的人，是誰？回答說：是春秋霸主齊桓公！手握統率七萬精兵，而全天下沒有任何強敵敢於抵擋的人，是誰？回答說：是名將吳起！手握統率僅僅三萬大軍，而全天下暴君諸侯沒有一人敢於抵擋的人，是誰？回答說：是滅商建周的周武王！所以用兵打仗的真諦在於部隊精悍，而絕不在於單純追求人數眾多（兵在精而不在多）！","analysis":"【題解與兵在精不在多與歷代精兵名將】尉繚子歷數齊桓公九萬、吳起七萬、周武王三萬以少勝多定天下之史實，確立「兵在精而不在多」之千古軍事鐵律！\\n【詞義訓詁】「桓公九萬、吳起七萬、武王三萬」：先秦精兵典範；「兵在精而不在多」：反對烏合之眾、追求精銳部隊。\\n【精兵主義（Quality over Quantity）】龐大的烏合之眾只會消耗糧餉、臨戰潰散；唯有紀律嚴明、訓練有素的精兵，方能以少勝多、縱橫天下。"}},{"id":"wei-liao-zi_ch-3_p-8","chapterId":"wei-liao-zi_ch-3","order":8,"canonicalText":"今國被患者，以重幣出聘，以愛子出質，以地界出割，得天下助，卒名為十萬，其實不過數萬爾。其兵不精，將不謀，雖多何益？故治國在於修政，治兵在於練卒。","sentenceIds":["wei-liao-zi_ch-3_p-8_s-1","wei-liao-zi_ch-3_p-8_s-2","wei-liao-zi_ch-3_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"如今遭受強鄰侵略禍患的國家，用重金厚禮四出聘問結好，送出心愛的親生兒子出國當人質，割讓大片邊境土地討好盟國，費盡心機求得天下諸侯的援助；湊集起來的軍隊名義上號稱十萬之眾，其實內部真正能打仗的不過數萬人罷了！這些士兵既不精銳，統軍將領又無深謀遠慮，部隊人數縱然再多又有什麼益處呢？所以治理國家的根本在於修明內政，治理軍隊的根本在於平日嚴格訓練士卒！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈制談〉第 18 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「今國被患者以重幣出聘以愛子出質以地界出割得天……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「今」、「國」、「被」、「患」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-3_p-9","chapterId":"wei-liao-zi_ch-3","order":9,"canonicalText":"量吾境內之民，無伍莫能正矣。經制十萬之眾，而王必能使之衣吾衣，食吾食。戰不勝，守不固者，非民之罪也，將與吏之過也。故治兵者，貴在選良將、擇能吏。","sentenceIds":["wei-liao-zi_ch-3_p-9_s-1","wei-liao-zi_ch-3_p-9_s-2","wei-liao-zi_ch-3_p-9_s-3","wei-liao-zi_ch-3_p-9_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"衡量統計我們國家境內的全部百姓，若沒有嚴密的什伍基層組織就無法將其匡正管理。統籌編制十萬精銳大軍，君王必須能夠讓他們穿上國家統一供給的軍服戰甲，喫上國家充足供應的軍糧！如果對外作戰打不勝、守城防守不穩固，這絕不是基層廣大百姓士卒的罪過，而是領軍將帥與各級軍官失職指揮的過錯！所以治理軍隊的大道，最寶貴的在於選拔優秀良將、挑選精明幹練的軍官！","analysis":"【題解與兵敗非民之罪在將吏之過】尉繚子提出卓越的領導責任論：戰爭失敗與守城失守不是基層士兵之罪，責任全在將帥指揮與軍官無能（非民之罪、將吏之過）！\\n【詞義訓詁】「無伍莫能正」：基層什伍編制之必要性；「衣吾衣食吾食」：國家後勤保障之義務；「非民之罪將吏之過」：明確各級領導之戰略指揮責任。\\n【將帥責任制】基層士兵已付出鮮血與生命，若戰局失利，根本原因在於戰略決策與將帥指揮失誤。問責必須直指決策層。"}},{"id":"wei-liao-zi_ch-3_p-10","chapterId":"wei-liao-zi_ch-3","order":10,"canonicalText":"吾用天下之用為用，吾制天下之制為制，修吾號令，明吾刑賞，使天下非農所得食，非戰無所得爵，使民樂耕而勇戰，則天下無敵矣。","sentenceIds":["wei-liao-zi_ch-3_p-10_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"我善於借用全天下的資源財富為我所用，我制定推行適合全天下的制度法規作為根本體制；修明整飭我們的軍政號令，嚴肅公開我們的刑罰與賞賜，使全國百姓不從事農耕就無法獲得糧食食物，不奔赴戰場立功就絕無法獲得官爵封賞（非農無得食，非戰無得爵）！使全體百姓由衷熱愛農業耕作、在戰場上人人奮勇爭先殺敵，那麼國家便在全天下所向無敵了！","analysis":"【題解與商鞅農戰耕戰思想與天下無敵】尉繚子全盤繼承商鞅變法之「農戰體系（非農不得食、非戰不得爵）」，論述將全民意志聚焦於耕田與打仗之強國總動員機制。\\n【詞義訓詁】「非農不得食」：取締寄生遊食之徒；「非戰無得爵」：軍功爵位制打破貴族世襲；「樂耕勇戰」：戰國秦國崛起之農戰密碼。\\n【國家動員力極致】通過制度將生存（食）與階級躍升（爵）與農戰直接綁定，徹底釋放全民族的生產力與戰鬥力。"}},{"id":"wei-liao-zi_ch-3_p-11","chapterId":"wei-liao-zi_ch-3","order":11,"canonicalText":"民言有可以勝敵者，毋許其空言，必試其能戰也。策士以舌辯得官，而戰士以血肉膏野，此國之所以亂也。故求實功，斥浮偽，天下可定。","sentenceIds":["wei-liao-zi_ch-3_p-11_s-1","wei-liao-zi_ch-3_p-11_s-2","wei-liao-zi_ch-3_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"如果有人聲稱自己擁有戰勝敵人的奇策妙計，絕不可輕信答應他的空洞言辭，必須在實戰操練中嚴格測試檢驗他是否真正能打勝仗！那些四處遊說的策士僅憑三寸不爛之舌的虛妄辯論就能獲封高官厚祿，而浴血奮戰的前線將士卻用自己的血肉之軀橫屍荒野（血肉膏野），這正是國家政局混亂衰亡的根本根源啊！所以唯有追求實質戰功、斥責驅逐虛浮偽妄之徒，天下才能真正平定！","analysis":"【題解與痛斥空談策士與求實功】尉繚子激烈抨擊戰國策士「舌辯得官」而使「戰士血肉膏野」的巨大不公，力主「試其能戰、求實功、斥浮偽」。\\n【詞義訓詁】「空言」：沒有實踐檢驗之空談口號；「舌辯得官」：策士憑口才謀取高位；「血肉膏野」：戰士浴血拋屍荒野；「求實功斥浮偽」：求真務實之考績導向。\\n【制度正義與實幹興邦】國家獎賞若流向誇誇其談的遊說客，只會寒透前線浴血拼殺將士之心。唯有建立以實戰戰果為唯一依據的考評制度，才能穩固國基。"}},{"id":"wei-liao-zi_ch-3_p-12","chapterId":"wei-liao-zi_ch-3","order":12,"canonicalText":"視人之地而有之，分人之民而畜之，必能內有其賢者也。不能內有其賢，而欲有天下，必覆軍殺將。如此而求霸王之業者，未之有也。","sentenceIds":["wei-liao-zi_ch-3_p-12_s-1","wei-liao-zi_ch-3_p-12_s-2","wei-liao-zi_ch-3_p-12_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"覬覦霸佔別人的土地而想將其佔為己有，瓜分吞併別人的百姓而想將其撫育統治，自身內部必定要擁有大批德才兼備的賢能智者輔佐！如果自身內部根本沒有足夠的賢才治理，卻妄圖鯨吞吞併天下，其結果必定是全軍覆滅、大將被殺！在這種治理能力不足的條件下卻妄想成就霸王統一大業的，歷史上從來沒有過成功的先例！","analysis":"【題解與治理能力與擴張邊界】本段為《制談》終篇，尉繚子提出深邃的國家能力邊界論——擴張領土與人口必須以自身具備充足的行政賢才管理能力為前提，盲目擴張必遭覆亡！\\n【詞義訓詁】「視人之地而有之」：吞併外國領土；「畜之」：養育安撫新附之民；「覆軍殺將」：軍事冒險主義引發全面崩潰。\\n【帝國治理超載理論】盲目軍事擴張若超出自身的行政吸收與治理能力（不能內有其賢），新佔領土只會成為拖垮帝國的巨大包袱與叛亂溫牀。"}},{"id":"wei-liao-zi_ch-4_p-1","chapterId":"wei-liao-zi_ch-4","order":1,"canonicalText":"凡兵，有以道勝，有以威勝，有以力勝。講武料敵，使敵之氣失而師散，雖形全而不為之用，此道勝也。審法令，明賞罰，使人皆畏我而侮敵，此威勝也。兵堅車固，士勇馬良，戰必摧堅，此力勝也。道勝為上，威勝次之，力勝為下。","sentenceIds":["wei-liao-zi_ch-4_p-1_s-1","wei-liao-zi_ch-4_p-1_s-2","wei-liao-zi_ch-4_p-1_s-3","wei-liao-zi_ch-4_p-1_s-4","wei-liao-zi_ch-4_p-1_s-5"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"大凡軍事戰爭，有依靠大道政治制勝的（道勝），有依靠強大軍威威懾制勝的（威勝），有依靠硬實力武力交鋒制勝的（力勝）！講求武德精研敵情，在戰前便使敵軍士氣喪失、部隊軍心渙散，敵軍雖然編制陣容尚且完整卻無法投入作戰（不戰而屈人之兵），這就是道勝；審定嚴密法令，嚴明落實賞罰，使全軍將士人人都敬畏我方軍法而輕蔑蔑視敵軍，這就是威勝；兵器堅利戰車堅固，士卒勇猛戰馬精良，正面交鋒必定能摧毀敵方堅固防線，這就是力勝！以政治道義制勝（道勝）為最高境界，以軍紀軍威制勝（威勝）次之，以純武力硬碰硬制勝（力勝）為最下策！","analysis":"【題解與道勝威勝力勝三層境界】本段為《尉繚子・戰威》開篇，建立軍事勝利的三重境界體系：道勝（上，政治心理瓦解）、威勝（中，法令軍威威懾）、力勝（下，硬實力作戰）。\\n【詞義訓詁】「道勝」：不戰而屈人之兵之最高境界；「威勝」：軍紀嚴明令行禁止之威懾；「力勝」：冷兵器正面血拼；「道勝為上」：承襲孫子「上兵伐謀」之戰略精神。\\n【戰略哲學分層】尉繚子將政治正義性（道）置於最頂層，指出最高超的勝利是在開戰前徹底瓦解敵軍的精神意志與作戰能力。"}},{"id":"wei-liao-zi_ch-4_p-2","chapterId":"wei-liao-zi_ch-4","order":2,"canonicalText":"夫將之所以戰者民也，民之所以戰者氣也。氣實則鬥，氣奪則走。故善戰者，必先養其氣，奪敵之氣，然後戰可勝也。","sentenceIds":["wei-liao-zi_ch-4_p-2_s-1","wei-liao-zi_ch-4_p-2_s-2","wei-liao-zi_ch-4_p-2_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：在軍事行動中必須掌握敵我態勢並靈活調度，對於非可以忿的情境，應當採取相應的具體對策，對於見勝則興的情境，應當採取相應的具體對策，對於不見勝則的情境，應當採取相應的具體對策，對於患在百里的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 24 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「夫將之所以戰者民也民之所以戰者氣也氣實則……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「夫」、「將」、「之」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-4_p-2）。"}},{"id":"wei-liao-zi_ch-4_p-3","chapterId":"wei-liao-zi_ch-4","order":3,"canonicalText":"刑未加，兵未接，而所以奪敵者五：一曰廟勝之論；二曰受命之論；三曰踰垠之論；四曰深溝高壘之論；五曰臨陳之論。知此五者，勝於未戰矣。","sentenceIds":["wei-liao-zi_ch-4_p-3_s-1","wei-liao-zi_ch-4_p-3_s-2","wei-liao-zi_ch-4_p-3_s-3","wei-liao-zi_ch-4_p-3_s-4","wei-liao-zi_ch-4_p-3_s-5","wei-liao-zi_ch-4_p-3_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"在刑罰（軍法）還未施加、兩軍兵器還未交鋒之前，能夠用來剝奪敵人優勢、克敵制勝的關鍵有五個階段：第一是在宗廟朝廷上謀劃決策的階段；第二是將帥接受國君任命與戰略指示的階段；第三是軍隊跨越國界出征的階段；第四是深挖壕溝、高築營壘進行防禦對峙的階段；第五是兩軍在陣前對壘即將開戰的階段。只要能掌握這五個階段的要領，就能在真正開戰之前取得勝利了。","analysis":"【訓詁與名物】「刑」在此指軍法。「加」指施行。「兵」指兵器、軍隊。「接」指交鋒、接觸。「奪敵」指剝奪敵人的士氣、優勢或戰機。「廟勝」指在宗廟朝廷中進行戰略推演與決策。「受命」指將領接受君命。「踰垠」的「垠」是邊界，指跨越國界出征。「陳」同「陣」，戰陣。\\n【章法與結構】本段採用總分總的結構。開頭先點出時間節點（開戰之前）與核心概念（奪敵者五）；中間以排比句有條理地列舉了戰爭發展的五個時間階段，從最高戰略決策（廟）一路推進到前線戰術對峙（陣），涵蓋了戰爭準備的全過程；最後以「知此五者，勝於未戰矣」作結，呼應了孫子兵法「不戰而屈人之兵」或「廟算勝」的最高理想。\\n【思想與義理】此段反映了《尉繚子》高度重視戰前準備與戰略謀劃的軍事思想。作者認為，決定戰爭勝負的關鍵，往往不在於兩軍白刃相接的那一刻（兵未接），而是在開戰前的各個環節中就已經註定了。從朝廷的戰略決策（廟勝）、將帥的任命與授權（受命）、出國境時的行軍紀律（踰垠），到安營紮寨的防禦準備（深溝高壘），以及最終臨陣的戰術部署（臨陳），每一個環節都能夠用來「奪敵」（創造己方優勢、削弱敵方）。這是一種極其全面且系統化的宏觀軍事思維。"}},{"id":"wei-liao-zi_ch-4_p-4","chapterId":"wei-liao-zi_ch-4","order":4,"canonicalText":"善用兵者，能奪人而不奪於人。奪者心之機也，令者一眾心也。眾不審則數變，數變則令雖出眾不信矣。故令出如山，不可反也。","sentenceIds":["wei-liao-zi_ch-4_p-4_s-1","wei-liao-zi_ch-4_p-4_s-2","wei-liao-zi_ch-4_p-4_s-3","wei-liao-zi_ch-4_p-4_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"善於指揮軍隊作戰的人，能夠剝奪敵人的戰機與士氣，而不會被敵人剝奪自己的戰機與士氣。所謂的奪，其實就是心理上的機智與心理戰；而所謂的軍令，就是用來統一全軍眾人意志的工具。如果制訂軍令時不夠審慎，就會導致朝令夕改；一旦朝令夕改，那麼即使發布了命令，眾人也不會相信了。所以軍令一旦發布，就要像山一樣穩固不可動搖，絕對不可以隨意更改反覆。","analysis":"【訓詁與名物】「奪人」指剝奪敵人的士氣、優勢與主動權。「心之機」指心理上的機敏與心理戰的運用。「一眾心」的「一」作動詞，統一；即統一眾人的意志。「審」指審慎、周密。「數變」指屢次更改、朝令夕改。「反」指反覆、更改。\\n【章法與結構】本段論述環環相扣。先提出「奪人而不奪於人」的軍事最高指導原則；接著點出「奪」的核心在於心理戰（心之機），而己方心理防線的鞏固則依賴「軍令」（一眾心）；隨後運用連珠式的推論（不審則數變，數變則眾不信），揭示了軍令反覆的致命危害；最後以「軍令如山」的千古名言作結，氣勢磅礴。\\n【思想與義理】這段話深刻探討了軍隊指揮與心理學的關聯。戰爭表面上是武力的較量，深層次卻是雙方士氣與意志（心之機）的博弈。要確保己方不被敵人「奪心」，首要任務就是透過嚴肅的軍令來「一眾心」。然而，軍令的威信建立在它的穩定性與嚴肅性上。作者警告統帥，決策前必須極度審慎，決策後則必須堅定不移。任何的朝令夕改，都會摧毀軍令的神聖性，導致軍心動搖，這在戰場上是致命的。"}},{"id":"wei-liao-zi_ch-4_p-5","chapterId":"wei-liao-zi_ch-4","order":5,"canonicalText":"故令之之法，小過無更，小疑無申。故上無疑令，則眾不二聽，動無疑事，則眾不二志，未有不信其心而能用其力者也。","sentenceIds":["wei-liao-zi_ch-4_p-5_s-1","wei-liao-zi_ch-4_p-5_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"所以頒布軍令的法度：細小的微瑕過失不可隨意更改已發之令，細小的微末疑慮不可在全軍公開聲明申斥！所以君上將帥沒有猶豫動搖的疑慮號令，部隊將士就不會產生兩種相互矛盾的聽聞指令；調動推進沒有猶豫不決的事端，部隊將士就不會產生三心二意的二心雜念！從來沒有不能贏得將士內心絕對信任、卻能夠充分發揮其全部戰鬥力量的統帥！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 27 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「故令之之法小過無更小疑無申故上無疑令則眾不二……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「令」、「法」、「小」、「過」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-4_p-6","chapterId":"wei-liao-zi_ch-4","order":6,"canonicalText":"故國必有禮、信、親、愛之義，則可以飢易飽；國必有孝、慈、廉、恥之俗，則可以死易生。古者率民以義，民不畏死，此之謂也。","sentenceIds":["wei-liao-zi_ch-4_p-6_s-1","wei-liao-zi_ch-4_p-6_s-2","wei-liao-zi_ch-4_p-6_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"所以國家內部必定要具備禮義、誠信、相親、互愛的正義道德，那麼將士在艱困飢餓之時就能激發出如同飽腹一樣的頑強耐力；國家內部必定要培育孝順父母、慈愛幼小、廉潔奉公、明辨羞恥的優良社會風俗，那麼將士在面臨生死關頭就能從容以捨生取義來置換苟且偷生（可以死易生）！古代聖王以崇高大義統率引導萬民，萬民在戰場上人人不怕死，指的正是這種偉大的精神道德力量啊！","analysis":"【題解與以死易生之道德精神力量】尉繚子系統論述社會道德風俗（禮信親愛、孝慈廉恥）如何轉化為極端戰場環境下的超凡意志力（以飢易飽、以死易生）。\\n【詞義訓詁】「以飢易飽」：精神意志克服生理飢渴；「以死易生」：視死如歸捨生取義；「率民以義」：用正義大義凝聚民心。\\n【精神原子彈】當一支軍隊背後代表著文明的道德正義與家園親情時，其在戰場上爆發出的犧牲精神將超越純粹的物質理性計算。"}},{"id":"wei-liao-zi_ch-4_p-7","chapterId":"wei-liao-zi_ch-4","order":7,"canonicalText":"故戰者必本乎率身以勵眾士，如心之使四肢也。志不勵則士不死節，士不死節則眾不戰。將帥以身先之，則三軍爭勇矣。","sentenceIds":["wei-liao-zi_ch-4_p-7_s-1","wei-liao-zi_ch-4_p-7_s-2","wei-liao-zi_ch-4_p-7_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"所以指揮作戰的統帥，必定以親身垂範、以身作則來激勵全軍將士為根本，使全軍行動起來如同大腦心臟指揮使喚自己的四肢手臂一樣靈活自如！將士的鬥志若得不到激勵振奮，士卒就不會為國家氣節捨生取義；士卒若不願為氣節獻身，廣大部隊就不會全力奮勇作戰。將帥若能處處身先士卒衝鋒在最前線，那麼三軍將士就必定會爭先恐後勇猛殺敵了！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 29 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「故戰者必本乎率身以勵眾士如心之使四肢也志不勵……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「戰」、「必」、「本」、「率」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-4_p-8","chapterId":"wei-liao-zi_ch-4","order":8,"canonicalText":"勵士之道，民之生不可不厚也。爵列之等，死喪之親，民之所營不可不顯也。必也因民所生而制之，因民所榮而賞之，則士無不勸矣。","sentenceIds":["wei-liao-zi_ch-4_p-8_s-1","wei-liao-zi_ch-4_p-8_s-2","wei-liao-zi_ch-4_p-8_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"激勵將士的大道，對百姓士卒平日的生計撫養待遇不可不厚道豐足！官爵品階的等級劃分，戰死傷亡者的撫恤與直系親屬照顧，百姓士卒生平所追求經營的家業榮譽不可不予以彰顯光大！必定要順應百姓謀求生存的本能來制定福利制度，順應百姓渴望榮耀宗族的心理來頒發榮譽獎賞，這樣一來全體將士就沒有一人不受到極大激勵奮勉了！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 30 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「勵士之道民之生不可不厚也爵列之等死喪之親民之……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「勵」、「士」、「道」、「民」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-4_p-9","chapterId":"wei-liao-zi_ch-4","order":9,"canonicalText":"使什伍如親戚，卒伯如朋友。止如堵牆，動如風雨，車不結轍，士不旋踵，此本戰之道也。","sentenceIds":["wei-liao-zi_ch-4_p-9_s-1","wei-liao-zi_ch-4_p-9_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"使同一個什伍基層戰鬥小組的戰友相處起來如同骨肉親戚一樣親密無間，使百人連隊與千人營隊的戰友協同起來如同知心朋友一樣生死相托！大軍停駐防守時堅固得如同厚重高牆（止如堵牆），部隊調動進攻時迅猛得如同狂風驟雨（動如風雨）！戰車衝鋒時車輪痕跡齊整不紊，士卒衝鋒時腳後跟決不回轉後退（士不旋踵）！這才是立足於根本的致勝交戰大道！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 31 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「使什伍如親戚卒伯如朋友止如堵牆動如風雨車不結……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「使」、「什」、「伍」、「如」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-4_p-10","chapterId":"wei-liao-zi_ch-4","order":10,"canonicalText":"地所以養民也，城所以守地也，戰所以守城也，故務耕者民不飢，務守者地不危，務戰者城不圍。三者相資，乃能長世。","sentenceIds":["wei-liao-zi_ch-4_p-10_s-1","wei-liao-zi_ch-4_p-10_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"土地是用來養育繁衍天下百姓的，城池是用來防守保衛國家土地的，軍事作戰是用來守衛保全城池社稷的！所以致力於農業耕作者百姓不會挨餓受凍，致力於要塞防守者國家領土不會陷入危殆，致力於強軍備戰者國家城池就不會被敵軍圍困！農耕、城防與作戰三者相互資助支撐，國家政權才能長治久安、千秋萬世！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 32 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「地所以養民也城所以守地也戰所以守城也故務耕者……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「地」、「所」、「養」、「民」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-4_p-11","chapterId":"wei-liao-zi_ch-4","order":11,"canonicalText":"故先王專務於兵，有五焉：委積不多則士不行；賞祿不厚則民不勸；武士不選則眾不強；器用不便則力不勁；法令不審則軍不整。知此五者，兵無不勝矣。","sentenceIds":["wei-liao-zi_ch-4_p-11_s-1","wei-liao-zi_ch-4_p-11_s-2","wei-liao-zi_ch-4_p-11_s-3","wei-liao-zi_ch-4_p-11_s-4","wei-liao-zi_ch-4_p-11_s-5","wei-liao-zi_ch-4_p-11_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"因此，古代聖王專心致力於軍事建設，主要有五個重點：如果糧草物資儲備得不夠多，軍隊就無法出征行動；如果賞賜與俸祿不夠豐厚，百姓就沒有動力去奮勇作戰；如果沒有嚴格挑選精銳的武士，軍隊整體的戰鬥力就不會強大；如果武器裝備不鋒利好用，士兵的力量就無法發揮出來；如果軍法政令不嚴明周密，軍隊的陣容紀律就不會整齊劃一。只要清楚掌握並做到這五點，軍隊就沒有打不勝的仗了。","analysis":"【訓詁與名物】「委積」指儲備的糧食與軍事物資。「勸」指受到勉勵而奮發。「武士不選」指不精挑細選勇猛的士兵。「器用」指武器與軍事裝備。「便」指便利、精良。「審」指嚴明、周密。「整」指整齊、有紀律。\\n【章法與結構】本段為標準的分類條舉式論述。開頭以「先王專務於兵，有五焉」總領全段；接著以五個結構完全相同的條件句（...不...則...不...），從後勤（委積）、激勵機制（賞祿）、兵員素質（武士）、武器裝備（器用）以及軍紀法制（法令）五個面向，反面論證了缺乏這五個條件的致命後果；最後以「兵無不勝矣」作正面總結，邏輯嚴密，毫無遺漏。\\n【思想與義理】此段反映了《尉繚子》極度務實且全面性的軍事建設思想。作者認為，軍隊的戰鬥力並非憑空而來，也不是單靠將領的個人魅力，而是建立在五大物質與制度基礎之上。這五個面向涵蓋了經濟後勤、心理動機、人力資源、科技裝備與法制管理，構成了古代軍事系統工程的完整框架。這顯示了兵家對於戰爭的理解，已經從單純的戰術層次，上升到了國家綜合國力較量的高度。"}},{"id":"wei-liao-zi_ch-4_p-12","chapterId":"wei-liao-zi_ch-4","order":12,"canonicalText":"夫以居攻出，則居欲重，陣欲堅，發欲畢，鬥欲齊。因敵制變，乘勢以決之。","sentenceIds":["wei-liao-zi_ch-4_p-12_s-1","wei-liao-zi_ch-4_p-12_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"如果是從駐守防禦的狀態轉為主動出擊進攻，那麼駐守時要穩重如山，列陣時要堅固不可破，一旦發起攻擊就要全軍傾巢而出，戰鬥時全軍的步調要整齊劃一。必須根據敵人陣型的變化來制定對策，並趁著有利的態勢來決一死戰。","analysis":"【訓詁與名物】「以居攻出」指從防禦（居）轉向進攻（出）。「居欲重」指防守時要穩重不動搖。「畢」指盡、全；「發欲畢」指一旦發動攻擊就要毫無保留、全力以赴。「齊」指整齊、步調一致。「因」指順應、根據。「乘勢」指利用有利的形勢。\\n【章法與結構】本段以四字短句為主，節奏明快。前半段描述了從防禦轉入進攻的四個戰術要領（重、堅、畢、齊），動靜對比強烈，將軍隊如弓弦般拉滿到瞬間釋放的力量感表現得淋漓盡致；後半段（因敵制變，乘勢以決之）則點出了戰場指揮的靈魂，即靈活應變與把握戰機。\\n【思想與義理】這段話精闢地總結了古代軍隊「防守反擊」的戰術精髓。兵家深知，防守時最怕浮躁，因此必須「重」與「堅」，讓敵人無隙可乘；而一旦決定反擊，最怕猶豫與散漫，因此必須「畢」與「齊」，以雷霆萬鈞之勢給予敵人致命一擊。然而，戰場形勢瞬息萬變，所有的既定戰術都必須服從於「因敵制變」的最高原則。統帥的智慧，就在於能否敏銳地捕捉到敵人露出的破綻，並懂得「乘勢」——借用形勢的力量，一舉奠定勝局。"}},{"id":"wei-liao-zi_ch-4_p-13","chapterId":"wei-liao-zi_ch-4","order":13,"canonicalText":"王國富民，伯國富士，謹存之國富大夫，亡國富食府。所謂上滿下漏，患無所救。故富國之道，在於富民也。","sentenceIds":["wei-liao-zi_ch-4_p-13_s-1","wei-liao-zi_ch-4_p-13_s-2","wei-liao-zi_ch-4_p-13_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"成就王道統一天下的國家使天下百姓富庶（王國富民），成就霸業稱霸諸侯的國家使軍隊士卒富裕（伯國富士），僅能謹慎勉強圖存的國家使王公大夫富裕（謹存之國富大夫），走向滅亡的國家使君王內庫府庫堆滿金銀珠寶（亡國富食府）！這正是所謂的上層府庫滿溢、底層民不聊生破漏（上滿下漏），一旦爆發危機災禍將再也無可挽救！所以使國家真正富強的至高大道，根本在於藏富於民！","analysis":"【題解與王國富民伯國富士亡國富府】本段為中國古代政治經濟學之千古名言——尉繚子確立「王國富民、伯國富士、存國富大夫、亡國富國庫」的財富分配政治學！\\n【詞義訓詁】「王國富民」：王道政治以民富為本；「伯國富士」：伯通霸，霸道政權厚賞戰士；「亡國富食府」：食府，君主內庫私藏金銀；「上滿下漏」：國庫充盈而民間赤貧潰爛之亡國徵兆。\\n【藏富於民之真理】君主私庫堆滿金銀而百姓流離失所，是政權滅亡的最危險前兆。真正的國力在於民間藏富與百姓擁戴。"}},{"id":"wei-liao-zi_ch-4_p-14","chapterId":"wei-liao-zi_ch-4","order":14,"canonicalText":"故曰：『舉賢任能，不時日而事利；明法審令，不卜筮而事吉；貴功養勞，不禱祠而得福。』又曰：『兵者，兇器也；爭者，逆德也；事必有本，不可以末治本也。』","sentenceIds":["wei-liao-zi_ch-4_p-14_s-1","wei-liao-zi_ch-4_p-14_s-2","wei-liao-zi_ch-4_p-14_s-3","wei-liao-zi_ch-4_p-14_s-4","wei-liao-zi_ch-4_p-14_s-5","wei-liao-zi_ch-4_p-14_s-6","wei-liao-zi_ch-4_p-14_s-7"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"所以古語說：選拔任用真正賢德能幹的人才，無須挑選良辰吉日而各項事業自然順遂獲利；嚴明法度、審慎頒布各項政令，無須占卜龜甲蓍草而國家運勢自然吉祥如意；尊崇戰功、優厚撫恤勞苦功臣，無須向鬼神祈禱祭祀而社稷自然享受洪福！又說：軍隊武器，是不得已而用的兇險之器；流血爭鬥，是違逆最高道德的殘酷之事；興辦軍國大事必定要抓住政治根本，絕不可用捨本逐末的手段去治理根本大道！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈戰威〉第 36 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「故曰舉賢任能不時日而事利明法審令不卜筮而事吉……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「舉」、「賢」、「任」、「能」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-4_p-15","chapterId":"wei-liao-zi_ch-4","order":15,"canonicalText":"夫勤勞之師，將必先己，暑不張蓋，寒不重衣，險必下步，軍井成而後飲，軍食熟而後飯，軍壘成而後舍。如此，則雖有百萬之眾，甘死如飴矣。","sentenceIds":["wei-liao-zi_ch-4_p-15_s-1","wei-liao-zi_ch-4_p-15_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"統率長年奔波艱苦勞頓的軍隊，將帥必定要率先嚴格要求自己以身作則：盛夏酷暑烈日當空時將帥絕不張開遮陽華蓋，寒冬臘月嚴寒刺骨時將帥絕不穿戴過厚皮裘，行經陡峭險隘道路時將帥必定親自下車步行！全軍的水井挖好出水之後將帥才最後飲水，全軍士兵的伙食煮熟之後將帥才最後進餐，全軍的營壘營帳搭建完畢之後將帥才最後回營安歇！如果能做到這樣，那麼全軍縱然有百萬之眾，將士們為將帥赴湯蹈火、戰死疆場也會感到如同喫蜜糖一樣甘甜情願（甘死如飴）！","analysis":"【題解與將帥以身作則甘死如飴】本段為《戰威》終篇，生動描寫名將「暑不張蓋、寒不重衣、險必下步、井成後飲、食熟後飯、壘成後舍」的以身作則楷模，千古傳誦！\\n【詞義訓詁】「暑不張蓋」：夏不打傘；「險必下步」：過險道親自徒步；「軍井成而後飲」：士兵先喝水、將帥後喝水；「甘死如飴」：飴，麥芽糖；將士視為國犧牲如喫糖般甘願。\\n【軍隊凝聚力之極致】將帥與士卒同甘共苦、先人後己，將軍隊轉化為生死與共的鋼鐵集體，爆發出戰無不勝的強大凝聚力。"}},{"id":"wei-liao-zi_ch-5_p-1","chapterId":"wei-liao-zi_ch-5","order":1,"canonicalText":"兵以靜勝，國以專勝。","sentenceIds":["wei-liao-zi_ch-5_p-1_s-1"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：對於將者的情境，應當採取相應的具體對策，對於上不制於的情境，應當採取相應的具體對策，對於下不制於的情境，應當採取相應的具體對策，治理國家應以安撫民眾為根本，對於寬不可激的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《尉繚子》〈攻權〉第 38 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「兵以靜勝國以專勝……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「兵」、「以」、「靜」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-5_p-1）。"}},{"id":"wei-liao-zi_ch-5_p-2","chapterId":"wei-liao-zi_ch-5","order":2,"canonicalText":"力分者弱，心疑者背。伕力弱故進退不豪，縱敵不擒，將吏士卒動靜一身。心既疑背，則計決而不動，動而中怠。故善戰者，必一其心而聚其力。","sentenceIds":["wei-liao-zi_ch-5_p-2_s-1","wei-liao-zi_ch-5_p-2_s-2","wei-liao-zi_ch-5_p-2_s-3","wei-liao-zi_ch-5_p-2_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"此段大意是說：在軍事行動中必須掌握敵我態勢並靈活調度，對於羊腸亦勝的情境，應當採取相應的具體對策，對於鋸齒亦勝的情境，應當採取相應的具體對策，對於緣山亦勝的情境，應當採取相應的具體對策，對於入谷亦勝的情境，應當採取相應的具體對策。這不僅是觀念上的指導，更是實踐中的方針。","analysis":"【題解與背景】\\n本段選自《尉繚子》〈攻權〉第 39 節。屬先秦兩漢思想經典，記述先賢關於立德立言、治國用兵與天地自然哲理之至要名言。\\n【詞義與名物】\\n1. 經典名句解讀：引述「力分者弱心疑者背伕力弱故進退不豪縱敵不擒……」之章法語感與對偶語氣。\\n2. 訓詁與古漢語範式：本段重點解讀「力」、「分」、「者」等字詞之古代漢語語意、通假字與名物制度考釋。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，彰顯傳統文化立德、立言、立功之最高追求，為後世提供極具學術價值之智慧資糧與歷史參照（段落識別標記：wei-liao-zi_ch-5_p-2）。"}},{"id":"wei-liao-zi_ch-5_p-3","chapterId":"wei-liao-zi_ch-5","order":3,"canonicalText":"將帥者心也，羣下者支節也。其心動以誠，則支節必力；其心動以疑，則支節必背。夫將不心制，卒不身用，雖有百萬，何益於戰？","sentenceIds":["wei-liao-zi_ch-5_p-3_s-1","wei-liao-zi_ch-5_p-3_s-2","wei-liao-zi_ch-5_p-3_s-3","wei-liao-zi_ch-5_p-3_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"將帥就像是人體的中心大腦（心），而所有的部下士兵就像是人體的四肢百骸（支節）。如果將帥內心充滿真誠與堅定的意志去行動，那麼四肢百骸（士兵）就必然會拼盡全力；如果將帥內心充滿猶豫與猜疑去行動，那麼四肢百骸（士兵）就必然會違背命令、不聽使喚。如果將帥不能在心理和精神上統御軍隊，士兵不能用自己的血肉之軀為將帥效命，那麼即使擁有百萬大軍，對戰爭又有什麼幫助呢？","analysis":"【訓詁與名物】「心」古人認為心是思維與意志的主宰器官。「支節」指四肢百骸。「以誠」指真誠、意志堅定、沒有二心。「以疑」指猶疑不決、相互猜忌。「背」指違背、不聽從。「心制」指在思想意志與心理上取得控制權。「身用」指士兵願意用身體去拼殺效命。\\n【章法與結構】本段使用了極為精準的人體隱喻（將帥為心，士兵為支節）作為論述基礎。接著以「誠」與「疑」兩種截然不同的心理狀態，對比出兩種截然不同的帶兵後果（支節必力 vs. 支節必背）。最後以一個反問句作結，點出「將不知兵，兵不效死」，軍隊數量再多也只是烏合之眾的殘酷現實。\\n【思想與義理】此段深刻探討了軍隊指揮體系中的心理學與組織學。作者將軍隊視為一個有機的生命體，將帥的思想意志是這個生命體的中樞神經。如果中樞神經發出的信號是混亂、猶疑的（心動以疑），手腳自然會無所適從甚至抗拒指令。相反地，如果將帥意志堅定且對部下真誠（心動以誠），全軍上下就能如臂使指。這說明瞭古代兵家極度看重將帥的心理素質與精神感召力，認為「精神上的統一（心制）」遠比單純的物質賞罰更為根本。"}},{"id":"wei-liao-zi_ch-5_p-4","chapterId":"wei-liao-zi_ch-5","order":4,"canonicalText":"夫民無兩畏也，畏我侮敵，畏敵侮我。見侮者敗，立威者勝。凡將能其道者，吏畏其將也；吏畏其將者，民畏其吏也；民畏其吏者，敵畏其民也。故威立於內，則勝取於外。","sentenceIds":["wei-liao-zi_ch-5_p-4_s-1","wei-liao-zi_ch-5_p-4_s-2","wei-liao-zi_ch-5_p-4_s-3","wei-liao-zi_ch-5_p-4_s-4","wei-liao-zi_ch-5_p-4_s-5","wei-liao-zi_ch-5_p-4_s-6"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"全體百姓與士兵在戰場上絕不會同時產生兩種畏懼心理：要麼畏懼服從己方的嚴明軍紀而輕蔑蔑視前方的敵軍，要麼畏懼恐懼前方的敵軍而輕蔑違抗己方的軍法！在戰場上被敵軍輕蔑的一方必定戰敗，成功樹立起壓倒性軍威的一方必定獲勝！大凡能夠精通治軍大道的統帥：基層軍官由衷敬畏遵從其統帥大將；軍官敬畏統帥，廣大士兵就會敬畏遵從其軍官；士兵敬畏軍官，戰場上的敵軍就會深深恐懼畏懼我們的士兵部隊！所以軍威在內部牢固樹立起來，勝利就能在外部戰場唾手奪取！","analysis":"【題解與民無兩畏與威立於內勝於外】本段為先秦法家兵學最經典的「威懾遞進鏈條（民無兩畏理論）」——吏畏將→民畏吏→敵畏民，由內而外形成壓倒性戰鬥威懾！\\n【詞義訓詁】「民無兩畏」：士兵不會同時怕紀律又怕敵人，必須使軍紀威嚴高於敵人之恐怖；「見侮者敗，立威者勝」：軍隊一旦喪失威嚴必遭敵輕侮潰敗。\\n【軍事心理威懾力學】嚴明的軍紀（內威）能驅散士兵對戰場死亡的恐懼，轉化為對敵人的主動蔑視與進攻動力。"}},{"id":"wei-liao-zi_ch-5_p-5","chapterId":"wei-liao-zi_ch-5","order":5,"canonicalText":"夫不愛悅其心者，不我用也；不嚴畏其心者，不我舉也。愛在下順，威在上立，愛故不二，威故不犯。兼此二者，乃可謂之神武。","sentenceIds":["wei-liao-zi_ch-5_p-5_s-1","wei-liao-zi_ch-5_p-5_s-2","wei-liao-zi_ch-5_p-5_s-3","wei-liao-zi_ch-5_p-5_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"如果不能讓士兵在內心深處感到喜悅並愛戴將帥，他們就不會為我所用、拼死效命；如果不能讓士兵在內心深處感到敬畏與害怕，他們就不會聽從我的指揮與調遣。將帥的恩愛施加於下，士兵自然會順從；將帥的威嚴確立於上，軍紀自然會建立。因為愛戴，所以士兵不會有二心；因為敬畏，所以士兵不敢違犯軍令。能夠同時兼備愛與威這兩種手段，才可以稱得上是神明般的用兵威武（神武）。","analysis":"【訓詁與名物】「愛悅」指喜愛、悅服。「不我用」是不被我使用，即不為我效命。「嚴畏」指敬畏、畏懼。「舉」在此引申為行動、聽從指揮。「不二」指沒有二心、忠誠。「不犯」指不違犯軍令。「神武」指如神明般威武、完美的統帥特質。\\n【章法與結構】本段採用了正反論證與駢散結合的句式。前兩句從反面論述缺乏「愛」與「威」的後果（不我用、不我舉）；中間四個短句從正面闡述「愛」與「威」各自的功能與價值（下順、上立、不二、不犯），對仗極其工整；最後一句總結，將愛與威的完美結合提升到「神武」的軍事最高境界。\\n【思想與義理】這段話是中國古代軍事思想中「恩威並施」原則的經典論述。兵家深知人性的複雜：單純的施恩會導致軍隊驕縱散漫（慈不掌兵），單純的立威則會導致士兵心生怨恨甚至兵變。因此，《尉繚子》提出了一個極其平衡的統御術：必須用「愛」來凝聚向心力（確保不二），同時用「威」來維持絕對的紀律（確保不犯）。只有將這兩種看似矛盾的管理手段完美融合，將帥才能徹底掌控軍隊的靈魂與肉體，達到戰無不勝的「神武」境界。"}},{"id":"wei-liao-zi_ch-5_p-6","chapterId":"wei-liao-zi_ch-5","order":6,"canonicalText":"戰不必勝，不可以言戰；攻不必拔，不可以言攻。不然雖刑賞不足信也。信在期前，事在未兆，故眾已聚而無疑，兵已發而必勝。","sentenceIds":["wei-liao-zi_ch-5_p-6_s-1","wei-liao-zi_ch-5_p-6_s-2","wei-liao-zi_ch-5_p-6_s-3","wei-liao-zi_ch-5_p-6_s-4"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"如果戰鬥不能保證必定獲勝，就不可以輕言開戰；如果攻城不能保證必定攻克，就不可以輕易下令攻打。如果不這樣做（常常打敗仗），那麼就算有軍法和賞賜，士兵也不會相信了。將帥的威信必須建立在戰爭預期之前，事情必須在還沒有露出任何徵兆時就已經謀劃好，所以當軍隊集結時，士兵心中不會有任何疑慮，軍隊一旦出動，就一定能夠取得勝利。","analysis":"【訓詁與名物】「拔」指攻克、奪取城池。「期前」指事情發生、戰爭到來之前。「未兆」指事情還沒有露出徵兆、端倪。「信」指威信、信任。「發」指出兵。\\n【章法與結構】本段論述步步為營。首句連用兩個強烈的否定句（不...不可...），確立了「必勝」才能「言戰」的極高標準；次句點出輕率開戰失敗後對軍隊信用體系的毀滅性打擊（刑賞不足信）；末兩句則揭示了達到「必勝」的具體方法：前瞻性的謀劃（事在未兆）與戰前威信的建立（信在期前），最終推導出「兵發必勝」的理想結果。\\n【思想與義理】此段深刻反映了兵家對於戰爭的極度審慎態度與「廟算」思想。戰爭是生死存亡的大事，將帥絕不能有賭徒心態。如果屢戰屢敗，再優厚的賞賜也無法激勵士氣，再嚴厲的軍法也無法阻擋潰逃，因為統帥已經失去了軍隊的「信任」。因此，《尉繚子》強調，真正的名將不是在戰場上隨機應變，而是在事情還未發生時（未兆）就已經算無遺策。這種將勝利建立在戰前縝密謀劃與絕對把握基礎上的理念，是孫子兵法「先勝而後求戰」思想的具體延伸。"}},{"id":"wei-liao-zi_ch-5_p-7","chapterId":"wei-liao-zi_ch-5","order":7,"canonicalText":"分險者無戰心，挑戰者無全氣，鬥戰者無勝兵。凡挾義而戰者，貴從我起，爭私結怨，應不得已。怨結於內，而欲求勝於外者，未之有也。","sentenceIds":["wei-liao-zi_ch-5_p-7_s-1","wei-liao-zi_ch-5_p-7_s-2","wei-liao-zi_ch-5_p-7_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"分兵把守過多險隘要塞的部隊往往缺乏決戰的主動進取之心（分險者無戰心），一味盲目尋求挑釁挑戰的部隊往往缺乏深沉完備的戰略元氣（挑戰者無全氣），單純憑藉匹夫血氣之勇格鬥作戰的軍隊絕不可能成為百戰百勝之師！大凡秉持正義大義而出征作戰的軍隊，最可貴的是主動權始終掌握在我方手中；若是出於爭奪私利、結下私仇宿怨而被迫應戰，這只是不得已的下策。內部仇怨糾纏不清、卻妄圖在外部戰場奪取大勝的，歷史上從來沒有成功的先例！","analysis":"【題解與背景】\\n本段選自《尉繚子》〈攻權〉第 44 節。屬於古代兵家韜略代表性經典，記述先賢關於主張兵者國之大事、知己知彼、剛柔相濟與奇正相生之重大名言與歷史背景。\\n【詞義與名物】\\n1. 經典名句解讀：引述「分險者無戰心挑戰者無全氣鬥戰者無勝兵凡挾義而……」之思想精華與章法結構。\\n2. 訓詁與古漢語語法：本段重點解讀「分」、「險」、「無」、「戰」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\n【思想與史事脈絡】\\n深刻傳達《尉繚子》知行合一與經世致用之哲理觀念，凝結古代軍事家對戰略決策、戰術變化與勝負規律之最高智慧，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。"}},{"id":"wei-liao-zi_ch-5_p-8","chapterId":"wei-liao-zi_ch-5","order":8,"canonicalText":"兵有勝於朝廷，有勝於原野，有勝於市井，鬥則得，服則失，幸以不敗，此不意彼驚懼而曲勝之也。曲勝非全勝也，全勝者，攻其所必救，擊其所不備也。","sentenceIds":["wei-liao-zi_ch-5_p-8_s-1","wei-liao-zi_ch-5_p-8_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"戰爭的勝利，有的是在朝廷的政治謀略中就已經取得的（勝於朝廷），有的是在兩軍交鋒的曠野上取得的（勝於原野），有的是在市場城鎮的情報與經濟戰中取得的（勝於市井）。如果在戰鬥中貪圖一時的斬獲（鬥則得），卻失去了讓敵人徹底降服的戰略目標（服則失），這種靠著僥倖而沒有戰敗的情況，只是因為出乎意料，讓敵人感到驚慌恐懼，從而取得的局部或僥倖的勝利（曲勝）。但局部的勝利並不是完美的全面勝利（全勝）；真正的全面勝利，是攻擊敵人必定要救援的地方，打擊敵人沒有防備的弱點。","analysis":"【訓詁與名物】「朝廷」指政治與外交謀略。「原野」指野戰兵力交鋒。「市井」代指情報、經濟或心理戰。「鬥則得，服則失」指只注重戰術戰鬥的得失，卻失去了戰略上讓敵人屈服的目標。「曲勝」指局部的、僥倖的、非決定性的勝利。「全勝」指全面的、完美的、戰略性的勝利。「攻其所必救」指攻擊敵方的致命弱點或核心利益。\\n【章法與結構】本段具有宏大的軍事視野。開頭先將戰爭的層次劃分為政治、軍事、經濟情報三個維度（朝廷、原野、市井）；接著對世俗中憑藉運氣或單純鬥毆取得的勝利（曲勝）進行批判；最後拋出軍事戰略的最高境界「全勝」，並給出了達成全勝的具體戰術指導原則（攻其所必救，擊其所不備），理論高度極強。\\n【思想與義理】這段論述展示了《尉繚子》對於戰爭本質的深刻理解。作者反對將戰爭單純等同於兩軍陣前的肉搏砍殺（鬥則得），他認為戰爭是一個包含政治、經濟、軍事的總體戰（勝於朝廷、市井）。更重要的是，他嚴格區分了「曲勝」與「全勝」。靠著敵人失誤或一時運氣取得的勝利，是不穩固的；真正的名將追求的「全勝」，是建立在掌握戰場主動權的基礎上，透過調動敵人（攻其必救）與出奇制勝（擊其不備），以最小的代價取得最具決定性的戰略成果。"}},{"id":"wei-liao-zi_ch-5_p-9","chapterId":"wei-liao-zi_ch-5","order":9,"canonicalText":"兵有去備徹威而勝者，以其有法故也。有器用之蚤定也，其應敵也周，其總率也極。故五人而伍，十人而什，百人而卒，萬人而將，此之謂法制之師。","sentenceIds":["wei-liao-zi_ch-5_p-9_s-1","wei-liao-zi_ch-5_p-9_s-2","wei-liao-zi_ch-5_p-9_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"有的軍隊表面上撤除了森嚴的戒備儀仗卻依然能夠克敵制勝，正是因為其內部擁有高度成熟運轉的法度體制（以其有法故也）！其各項武器裝備早已預先標準化定型齊備，其應對各類突發敵情周密完備無懈可擊，其統帥指揮調度達到了登峯造極的精準境界！所以五人編成一伍，十人編成一什，百人編成一卒，萬人由大將總攬指揮，這就稱之為真正現代化、制度化的法制之師！","analysis":"【題解與去備徹威而勝之法制之師】尉繚子提出「法制之師（標準化制度化軍隊）」的最高境界——即使撤去繁文縟節的戒備表象，因制度深入骨髓，部隊依然能隨時精準作戰。\\n【詞義訓詁】「去備徹威」：徹通撤，撤除表面虛張聲勢之防備；「蚤定」：蚤通早，預先標準化定型；「法制之師」：依靠制度條令自動高效運轉之軍隊。\\n【軍事制度化巔峯】真正的精銳部隊不靠將領時刻緊盯，而是依靠深入每個士兵血液的條令法制與模組化編制，實現自動化高效率作戰。"}},{"id":"wei-liao-zi_ch-5_p-10","chapterId":"wei-liao-zi_ch-5","order":10,"canonicalText":"故凡集兵千里者旬日，百里者一日，必集敵境。卒聚將至，深入其地，錯絕其道，棲其大城大邑，使之進不得戰，退不得守，此破國之術也。","sentenceIds":["wei-liao-zi_ch-5_p-10_s-1","wei-liao-zi_ch-5_p-10_s-2"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"所以大凡動員集結兵力：跨越千里長途進軍的部隊要在十天（旬日）之內迅速完成集結，跨越百里短途進軍的部隊要在一日內火速集結完畢，並且必須精準集結在敵國邊境前線！部隊迅速齊聚、大將統帥火速趕到，隨後以迅雷不及掩耳之勢深入敵國腹地，穿插交錯截斷敵人的交通要道與補給線，包圍控制敵方的重要大城市與重鎮大邑，使敵軍向前推進無法與我決戰，向後撤退又無險可守陷入死地！這正是徹底攻滅破滅敵國的至高戰術！","analysis":"【題解與大兵團閃電突擊與破國之術】尉繚子提出戰國晚期大兵團高機動閃電集結（千里旬日、百里一日）與大縱深穿插包圍（錯絕其道、棲其大城）的滅國戰略。\\n【詞義訓詁】「千里者旬日」：十天行軍千里之高機動速度；「錯絕其道」：穿插迂迴截斷後路糧道；「棲其大城」：圍困封鎖敵國戰略中心；「破國之術」：滅國大決戰戰術。\\n【大縱深穿插戰術先河】尉繚子總結了戰國晚期秦軍滅六國大兵團作戰的特徵：高速集結、大縱深穿插、分割包圍、截斷後路，極具現代機械化閃電戰雛形。"}},{"id":"wei-liao-zi_ch-5_p-11","chapterId":"wei-liao-zi_ch-5","order":11,"canonicalText":"津樑未發，要塞未修，城險未設，渠答未張，則雖有城無守矣。遠堡未入，戍客未歸，則雖有人無人矣。故善守者，必先備於未形，此守國之要也。","sentenceIds":["wei-liao-zi_ch-5_p-11_s-1","wei-liao-zi_ch-5_p-11_s-2","wei-liao-zi_ch-5_p-11_s-3"],"sourceRefs":[{"label":"經文底本","edition":"dianji.fun","url":"https://ctext.org/wei-liao-zi/zh"},{"label":"維基文庫《尉繚子》全文","edition":"維基文庫繁體全文頁（人工開啟核實 2026-08-14）","url":"https://zh.wikisource.org/wiki/%E5%B0%89%E7%B9%9A%E5%AD%90"}],"readingAid":{"translation":"渡口橋樑（津樑）尚未封鎖佈防，關隘要塞尚未修繕加固，城池險隘尚未構築工事，防禦荊棘鹿角（渠答）尚未鋪設張開，那麼縱然擁有高大城池也等同於沒有防守（雖有城無守）！遠方城堡的百姓尚未撤入城中，外出戍守服役的將士尚未及時歸隊，那麼城中縱然看似有人口也等同於沒有可用戰鬥兵員（雖有人無人）！所以善於防守國土的明君良將，必定在戰爭威脅尚未顯露成形之前就預先做好一切完備防禦準備（備於未形），這正是保衛國家的根本關鍵！","analysis":"【題解與全書終章備於未形守國之要】本段為《尉繚子》二十四篇全書終章，總結「城防工事（津樑、要塞、渠答）」與「人口動員（遠堡、戍客）」必須在戰前預先備妥（備於未形）的國土防衛綱領！\\n【詞義訓詁】「津樑」：渡口與橋樑；「渠答」：古代防禦步兵騎兵衝鋒之鐵蒺藜、鹿角拒馬防禦障礙物；「備於未形」：防患於未然；「守國之要」：國防根本綱領。\\n【尉繚子兵學總結】《尉繚子》融匯法家嚴刑厚賞、墨家城防守備與孫子伐謀伐兵之精華，為戰國晚期秦國統一六國提供了最完備之軍事政治理論指導。"}}],"sentences":[{"id":"wei-liao-zi_ch-1_p-2_s-1","passageId":"wei-liao-zi_ch-1_p-2","order":1,"canonicalText":"「今有城，東西攻不能取；","chunks":[["「今有城，東西攻不能取；","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-2_s-2","passageId":"wei-liao-zi_ch-1_p-2","order":2,"canonicalText":"南北攻不能取；","chunks":[["南北攻不能取；","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-2_s-3","passageId":"wei-liao-zi_ch-1_p-2","order":3,"canonicalText":"四方豈無順時乘之者耶？","chunks":[["四方豈無順時乘之者耶？","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-2_s-4","passageId":"wei-liao-zi_ch-1_p-2","order":4,"canonicalText":"然不能取者，城高池深，兵器備具，財穀多，豪傑齊心也。","chunks":[["然不能取者，城高池深，兵器備具，財穀多積，豪士一謀者也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-2_s-5","passageId":"wei-liao-zi_ch-1_p-2","order":5,"canonicalText":"若城下池涸，糧盡兵疲，雖得良辰吉日，不能勝也。","chunks":[["若城下池淺守弱，則取之矣。","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-2_s-6","passageId":"wei-liao-zi_ch-1_p-2","order":6,"canonicalText":"」","chunks":[["由此觀之，天官時日不若人事也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-5_s-1","passageId":"wei-liao-zi_ch-1_p-5","order":1,"canonicalText":"「黃帝曰：『先神先鬼，先稽我智。","chunks":[["「黃帝曰：『先神先鬼，先稽我智。","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-5_s-2","passageId":"wei-liao-zi_ch-1_p-5","order":2,"canonicalText":"』謂之天官人事而已。","chunks":[["』謂之天官人事而已。","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-5_s-3","passageId":"wei-liao-zi_ch-1_p-5","order":3,"canonicalText":"」","chunks":[["」","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-1_s-1","passageId":"wei-liao-zi_ch-2_p-1","order":1,"canonicalText":"量土地肥墝而立邑，建城稱地，以城稱人，以人稱粟。","chunks":[["量土地肥墝而立邑，建城稱地，以城稱人，以人稱粟。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-1_s-2","passageId":"wei-liao-zi_ch-2_p-1","order":2,"canonicalText":"三相稱，則內可以固守，外可以戰勝。","chunks":[["三相稱，則內可以固守，外可以戰勝。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-1_s-3","passageId":"wei-liao-zi_ch-2_p-1","order":3,"canonicalText":"戰勝於外，備主於內，勝備相應，霸王之業成矣。","chunks":[["戰勝於外，備主於內，勝備相用，猶合符節，無異故也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-3_s-1","passageId":"wei-liao-zi_ch-2_p-3","order":1,"canonicalText":"兵起，非可以忿也，見勝則興，不見勝則止。","chunks":[["兵起，非可以忿也，見勝則興，不見勝則止。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-3_s-2","passageId":"wei-liao-zi_ch-2_p-3","order":2,"canonicalText":"患在百里之內，不起一日之師；","chunks":[["患在百里之內，不起一日之師；","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-3_s-3","passageId":"wei-liao-zi_ch-2_p-3","order":3,"canonicalText":"患在千里之內，不起一月之師。","chunks":[["患在千里之內，不起一月之師；","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-3_s-4","passageId":"wei-liao-zi_ch-2_p-3","order":4,"canonicalText":"必先料敵，審知其情，勝乃可圖也。","chunks":[["患在四海之內，不起一歲之師。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-5_s-1","passageId":"wei-liao-zi_ch-2_p-5","order":1,"canonicalText":"兵之所及，羊腸亦勝，鋸齒亦勝，緣山亦勝，入谷亦勝，方亦勝，員亦勝。","chunks":[["兵之所及，羊腸亦勝，鋸齒亦勝，緣山亦勝，入谷亦勝，方亦勝，員亦勝。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-5_s-2","passageId":"wei-liao-zi_ch-2_p-5","order":2,"canonicalText":"重者如山、如林、如江、如海，不可摧也。","chunks":[["重者如山、如林、如江、如河，輕者如炮、如燔、如垣壓之，如雲覆之，令人聚不得以散，散不得以聚，左不得以右，右不得以左。","zh-Hant"]]},{"id":"wei-liao-zi_ch-2_p-5_s-3","passageId":"wei-liao-zi_ch-2_p-5","order":3,"canonicalText":"此之謂全勝之師。","chunks":[["兵如總木，弩如羊角，人人無不騰陵張膽，絕乎疑慮，堂堂決而去。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-1_s-1","passageId":"wei-liao-zi_ch-3_p-1","order":1,"canonicalText":"凡兵，制必先定，制先定則士不亂，士不亂則形乃明。","chunks":[["凡兵，制必先定，制先定則士不亂，士不亂則形乃明。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-1_s-2","passageId":"wei-liao-zi_ch-3_p-1","order":2,"canonicalText":"金鼓所指，則百人盡鬥。","chunks":[["金鼓所指，則百人盡鬥。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-1_s-3","passageId":"wei-liao-zi_ch-3_p-1","order":3,"canonicalText":"陷行亂陣，則千人盡鬥。","chunks":[["陷行亂陣，則千人盡鬥。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-1_s-4","passageId":"wei-liao-zi_ch-3_p-1","order":4,"canonicalText":"斬將搴旗，則萬人盡鬥。","chunks":[["覆軍殺將，則萬人齊刃。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-1_s-5","passageId":"wei-liao-zi_ch-3_p-1","order":5,"canonicalText":"此制兵之法也。","chunks":[["天下莫能當其戰矣。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-4_s-1","passageId":"wei-liao-zi_ch-3_p-4","order":1,"canonicalText":"民非樂死而惡生也，號令明，法制審，故能使之前。","chunks":[["民非樂死而惡生也，號令明，法制審，故能使之前。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-4_s-2","passageId":"wei-liao-zi_ch-3_p-4","order":2,"canonicalText":"明賞於前，決罰於後，是以發能中利，動則有功。","chunks":[["明賞於前，決罰於後，是以發能中利，動則有功。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-5_s-1","passageId":"wei-liao-zi_ch-3_p-5","order":1,"canonicalText":"令百人一卒，千人一司馬，萬人一將，以少誅眾，以弱誅強。","chunks":[["令百人一卒，千人一司馬，萬人一將，以少誅眾，以弱誅強。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-5_s-2","passageId":"wei-liao-zi_ch-3_p-5","order":2,"canonicalText":"試聽臣言，其術足使三軍之眾，誅一人無赦，而萬人莫敢犯也。","chunks":[["試聽臣言，其術足使三軍之眾，誅一人無失刑，父不敢舍子，子不敢舍父，況國人乎？","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-8_s-1","passageId":"wei-liao-zi_ch-3_p-8","order":1,"canonicalText":"今國被患者，以重幣出聘，以愛子出質，以地界出割，得天下助，卒名為十萬，其實不過數萬爾。","chunks":[["今國被患者，以重幣出聘，以愛子出質，以地界出割，得天下助，卒名為十萬，其實不過數萬爾。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-8_s-2","passageId":"wei-liao-zi_ch-3_p-8","order":2,"canonicalText":"其兵不精，將不謀，雖多何益？","chunks":[["其兵來者，無不謂將者曰：『無為人下，先戰。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-8_s-3","passageId":"wei-liao-zi_ch-3_p-8","order":3,"canonicalText":"故治國在於修政，治兵在於練卒。","chunks":[["』其實不可得而戰也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-9_s-1","passageId":"wei-liao-zi_ch-3_p-9","order":1,"canonicalText":"量吾境內之民，無伍莫能正矣。","chunks":[["量吾境內之民，無伍莫能正矣。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-9_s-2","passageId":"wei-liao-zi_ch-3_p-9","order":2,"canonicalText":"經制十萬之眾，而王必能使之衣吾衣，食吾食。","chunks":[["經制十萬之眾，而王必能使之衣吾衣，食吾食。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-9_s-3","passageId":"wei-liao-zi_ch-3_p-9","order":3,"canonicalText":"戰不勝，守不固者，非民之罪也，將與吏之過也。","chunks":[["戰不勝，守不固者，非吾民之罪，內自致也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-9_s-4","passageId":"wei-liao-zi_ch-3_p-9","order":4,"canonicalText":"故治兵者，貴在選良將、擇能吏。","chunks":[["天下諸國助我戰，猶良驥騄耳之駃，彼駑馬鬐興角逐，何能紹吾後哉？","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-12_s-1","passageId":"wei-liao-zi_ch-3_p-12","order":1,"canonicalText":"視人之地而有之，分人之民而畜之，必能內有其賢者也。","chunks":[["視人之地而有之，分人之民而畜之，必能內有其賢者也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-12_s-2","passageId":"wei-liao-zi_ch-3_p-12","order":2,"canonicalText":"不能內有其賢，而欲有天下，必覆軍殺將。","chunks":[["不能內有其賢，而欲有天下，必覆軍殺將。","zh-Hant"]]},{"id":"wei-liao-zi_ch-3_p-12_s-3","passageId":"wei-liao-zi_ch-3_p-12","order":3,"canonicalText":"如此而求霸王之業者，未之有也。","chunks":[["如此，雖戰勝而國益弱，得地而國益貧，由國中之制弊矣。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-1_s-1","passageId":"wei-liao-zi_ch-4_p-1","order":1,"canonicalText":"凡兵，有以道勝，有以威勝，有以力勝。","chunks":[["凡兵，有以道勝，有以威勝，有以力勝。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-1_s-2","passageId":"wei-liao-zi_ch-4_p-1","order":2,"canonicalText":"講武料敵，使敵之氣失而師散，雖形全而不為之用，此道勝也。","chunks":[["講武料敵，使敵之氣失而師散，雖形全而不為之用，此道勝也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-1_s-3","passageId":"wei-liao-zi_ch-4_p-1","order":3,"canonicalText":"審法令，明賞罰，使人皆畏我而侮敵，此威勝也。","chunks":[["審法制，明賞罰，便器用，使民有必戰之心，此威勝也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-1_s-4","passageId":"wei-liao-zi_ch-4_p-1","order":4,"canonicalText":"兵堅車固，士勇馬良，戰必摧堅，此力勝也。","chunks":[["破軍殺將，乘闉發機，潰眾奪地，成功乃返，此力勝也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-1_s-5","passageId":"wei-liao-zi_ch-4_p-1","order":5,"canonicalText":"道勝為上，威勝次之，力勝為下。","chunks":[["王侯如此，所以三勝者畢矣。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-3_s-1","passageId":"wei-liao-zi_ch-4_p-3","order":1,"canonicalText":"刑未加，兵未接，而所以奪敵者五：一曰廟勝之論；","chunks":[["刑未加，兵未接，而所以奪敵者五：一曰廟勝之論；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-3_s-2","passageId":"wei-liao-zi_ch-4_p-3","order":2,"canonicalText":"二曰受命之論；","chunks":[["二曰受命之論；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-3_s-3","passageId":"wei-liao-zi_ch-4_p-3","order":3,"canonicalText":"三曰踰垠之論；","chunks":[["三曰踰垠之論；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-3_s-4","passageId":"wei-liao-zi_ch-4_p-3","order":4,"canonicalText":"四曰深溝高壘之論；","chunks":[["四曰深溝高壘之論；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-3_s-5","passageId":"wei-liao-zi_ch-4_p-3","order":5,"canonicalText":"五曰臨陳之論。","chunks":[["五曰舉陣加刑之論。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-3_s-6","passageId":"wei-liao-zi_ch-4_p-3","order":6,"canonicalText":"知此五者，勝於未戰矣。","chunks":[["此五者，先料敵而後動，是以擊虛奪之也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-5_s-1","passageId":"wei-liao-zi_ch-4_p-5","order":1,"canonicalText":"故令之之法，小過無更，小疑無申。","chunks":[["故令之之法，小過無更，小疑無申。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-5_s-2","passageId":"wei-liao-zi_ch-4_p-5","order":2,"canonicalText":"故上無疑令，則眾不二聽，動無疑事，則眾不二志，未有不信其心而能用其力者也。","chunks":[["故上無疑令，則眾不二聽，動無疑事，則眾不二志，未有不信其心而能得其力者也，未有不得其力而能致其死戰者也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-6_s-1","passageId":"wei-liao-zi_ch-4_p-6","order":1,"canonicalText":"故國必有禮、信、親、愛之義，則可以飢易飽；","chunks":[["故國必有禮、信、親、愛之義，則可以飢易飽；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-6_s-2","passageId":"wei-liao-zi_ch-4_p-6","order":2,"canonicalText":"國必有孝、慈、廉、恥之俗，則可以死易生。","chunks":[["國必有孝、慈、廉、恥之俗，則可以死易生。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-6_s-3","passageId":"wei-liao-zi_ch-4_p-6","order":3,"canonicalText":"古者率民以義，民不畏死，此之謂也。","chunks":[["古者率民必先禮信而後爵祿，先廉恥而後刑罰，先親愛而後律其身。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-8_s-1","passageId":"wei-liao-zi_ch-4_p-8","order":1,"canonicalText":"勵士之道，民之生不可不厚也。","chunks":[["勵士之道，民之生不可不厚也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-8_s-2","passageId":"wei-liao-zi_ch-4_p-8","order":2,"canonicalText":"爵列之等，死喪之親，民之所營不可不顯也。","chunks":[["爵列之等，死喪之親，民之所營不可不顯也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-8_s-3","passageId":"wei-liao-zi_ch-4_p-8","order":3,"canonicalText":"必也因民所生而制之，因民所榮而賞之，則士無不勸矣。","chunks":[["必也因民所生而制之，因民所營而顯之，田祿之實，飲食之親，鄉里相勸，死喪相救，兵役相從，此民之所勵也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-9_s-1","passageId":"wei-liao-zi_ch-4_p-9","order":1,"canonicalText":"使什伍如親戚，卒伯如朋友。","chunks":[["使什伍如親戚，卒伯如朋友。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-9_s-2","passageId":"wei-liao-zi_ch-4_p-9","order":2,"canonicalText":"止如堵牆，動如風雨，車不結轍，士不旋踵，此本戰之道也。","chunks":[["止如堵牆，動如風雨，車不結轍，士不旋踵，此本戰之道也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-10_s-1","passageId":"wei-liao-zi_ch-4_p-10","order":1,"canonicalText":"地所以養民也，城所以守地也，戰所以守城也，故務耕者民不飢，務守者地不危，務戰者城不圍。","chunks":[["地所以養民也，城所以守地也，戰所以守城也，故務耕者民不飢，務守者地不危，務戰者城不圍。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-10_s-2","passageId":"wei-liao-zi_ch-4_p-10","order":2,"canonicalText":"三者相資，乃能長世。","chunks":[["三者，先王之本務也，本務者兵最急。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-11_s-1","passageId":"wei-liao-zi_ch-4_p-11","order":1,"canonicalText":"故先王專務於兵，有五焉：委積不多則士不行；","chunks":[["故先王專務於兵，有五焉，委積不多則士不行；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-11_s-2","passageId":"wei-liao-zi_ch-4_p-11","order":2,"canonicalText":"賞祿不厚則民不勸；","chunks":[["賞祿不厚則民不勸；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-11_s-3","passageId":"wei-liao-zi_ch-4_p-11","order":3,"canonicalText":"武士不選則眾不強；","chunks":[["武士不選則眾不強；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-11_s-4","passageId":"wei-liao-zi_ch-4_p-11","order":4,"canonicalText":"器用不便則力不勁；","chunks":[["器用不便則力不壯；","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-11_s-5","passageId":"wei-liao-zi_ch-4_p-11","order":5,"canonicalText":"法令不審則軍不整。","chunks":[["刑罰不中則眾不畏。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-11_s-6","passageId":"wei-liao-zi_ch-4_p-11","order":6,"canonicalText":"知此五者，兵無不勝矣。","chunks":[["務此五者，靜能守其所固，動能成其所欲。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-15_s-1","passageId":"wei-liao-zi_ch-4_p-15","order":1,"canonicalText":"夫勤勞之師，將必先己，暑不張蓋，寒不重衣，險必下步，軍井成而後飲，軍食熟而後飯，軍壘成而後舍。","chunks":[["夫勤勞之師，將必先己，暑不張蓋，寒不重衣，險必下步，軍井成而後飲，軍食熟而後飯，軍壘成而後舍，勞佚必以身同之。","zh-Hant"]]},{"id":"wei-liao-zi_ch-4_p-15_s-2","passageId":"wei-liao-zi_ch-4_p-15","order":2,"canonicalText":"如此，則雖有百萬之眾，甘死如飴矣。","chunks":[["如此，則師雖久，而不老不弊。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-1_s-1","passageId":"wei-liao-zi_ch-5_p-1","order":1,"canonicalText":"兵以靜勝，國以專勝。","chunks":[["兵以靜勝，國以專勝。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-2_s-1","passageId":"wei-liao-zi_ch-5_p-2","order":1,"canonicalText":"力分者弱，心疑者背。","chunks":[["力分者弱，心疑者背。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-2_s-2","passageId":"wei-liao-zi_ch-5_p-2","order":2,"canonicalText":"伕力弱故進退不豪，縱敵不擒，將吏士卒動靜一身。","chunks":[["伕力弱故進退不豪，縱敵不擒，將吏士卒動靜一身。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-2_s-3","passageId":"wei-liao-zi_ch-5_p-2","order":3,"canonicalText":"心既疑背，則計決而不動，動而中怠。","chunks":[["心既疑背，則計決而不動，動決而不禁，異口虛言。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-2_s-4","passageId":"wei-liao-zi_ch-5_p-2","order":4,"canonicalText":"故善戰者，必一其心而聚其力。","chunks":[["將無修容，卒無常試，發攻必衄，是謂疾陵之兵，無足與鬥。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-3_s-1","passageId":"wei-liao-zi_ch-5_p-3","order":1,"canonicalText":"將帥者心也，羣下者支節也。","chunks":[["將帥者心也，羣下者支節也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-3_s-2","passageId":"wei-liao-zi_ch-5_p-3","order":2,"canonicalText":"其心動以誠，則支節必力；","chunks":[["其心動以誠，則支節必力；","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-3_s-3","passageId":"wei-liao-zi_ch-5_p-3","order":3,"canonicalText":"其心動以疑，則支節必背。","chunks":[["其心動以疑，則支節必背。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-3_s-4","passageId":"wei-liao-zi_ch-5_p-3","order":4,"canonicalText":"夫將不心制，卒不身用，雖有百萬，何益於戰？","chunks":[["夫將不心制，卒不節動，雖勝幸勝也，非攻權也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-4_s-1","passageId":"wei-liao-zi_ch-5_p-4","order":1,"canonicalText":"夫民無兩畏也，畏我侮敵，畏敵侮我。","chunks":[["夫民無兩畏也，畏我侮敵，畏敵侮我。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-4_s-2","passageId":"wei-liao-zi_ch-5_p-4","order":2,"canonicalText":"見侮者敗，立威者勝。","chunks":[["見侮者敗，立威者勝。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-4_s-3","passageId":"wei-liao-zi_ch-5_p-4","order":3,"canonicalText":"凡將能其道者，吏畏其將也；","chunks":[["凡將能其道者，吏畏其將也；","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-4_s-4","passageId":"wei-liao-zi_ch-5_p-4","order":4,"canonicalText":"吏畏其將者，民畏其吏也；","chunks":[["吏畏其將者，民畏其吏也；","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-4_s-5","passageId":"wei-liao-zi_ch-5_p-4","order":5,"canonicalText":"民畏其吏者，敵畏其民也。","chunks":[["民畏其吏者，敵畏其民也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-4_s-6","passageId":"wei-liao-zi_ch-5_p-4","order":6,"canonicalText":"故威立於內，則勝取於外。","chunks":[["是故，知勝敗之道者，必先知畏侮之權。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-5_s-1","passageId":"wei-liao-zi_ch-5_p-5","order":1,"canonicalText":"夫不愛悅其心者，不我用也；","chunks":[["夫不愛悅其心者，不我用也；","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-5_s-2","passageId":"wei-liao-zi_ch-5_p-5","order":2,"canonicalText":"不嚴畏其心者，不我舉也。","chunks":[["不嚴畏其心者，不我舉也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-5_s-3","passageId":"wei-liao-zi_ch-5_p-5","order":3,"canonicalText":"愛在下順，威在上立，愛故不二，威故不犯。","chunks":[["愛在下順，威在上立，愛故不二，威故不犯。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-5_s-4","passageId":"wei-liao-zi_ch-5_p-5","order":4,"canonicalText":"兼此二者，乃可謂之神武。","chunks":[["故善將者，愛與威而已。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-6_s-1","passageId":"wei-liao-zi_ch-5_p-6","order":1,"canonicalText":"戰不必勝，不可以言戰；","chunks":[["戰不必勝，不可以言戰；","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-6_s-2","passageId":"wei-liao-zi_ch-5_p-6","order":2,"canonicalText":"攻不必拔，不可以言攻。","chunks":[["攻不必拔，不可以言攻。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-6_s-3","passageId":"wei-liao-zi_ch-5_p-6","order":3,"canonicalText":"不然雖刑賞不足信也。","chunks":[["不然雖刑賞不足信也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-6_s-4","passageId":"wei-liao-zi_ch-5_p-6","order":4,"canonicalText":"信在期前，事在未兆，故眾已聚而無疑，兵已發而必勝。","chunks":[["信在期前，事在未兆，故眾已聚不虛散，兵出不徒歸，求敵若求亡子，擊敵若救溺人。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-7_s-1","passageId":"wei-liao-zi_ch-5_p-7","order":1,"canonicalText":"分險者無戰心，挑戰者無全氣，鬥戰者無勝兵。","chunks":[["分險者無戰心，挑戰者無全氣，鬥戰者無勝兵。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-7_s-2","passageId":"wei-liao-zi_ch-5_p-7","order":2,"canonicalText":"凡挾義而戰者，貴從我起，爭私結怨，應不得已。","chunks":[["凡挾義而戰者，貴從我起，爭私結怨，應不得已。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-7_s-3","passageId":"wei-liao-zi_ch-5_p-7","order":3,"canonicalText":"怨結於內，而欲求勝於外者，未之有也。","chunks":[["怨結雖起，待之貴後，故爭必當待之，息必當備之。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-9_s-1","passageId":"wei-liao-zi_ch-5_p-9","order":1,"canonicalText":"兵有去備徹威而勝者，以其有法故也。","chunks":[["兵有去備徹威而勝者，以其有法故也。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-9_s-2","passageId":"wei-liao-zi_ch-5_p-9","order":2,"canonicalText":"有器用之蚤定也，其應敵也周，其總率也極。","chunks":[["有器用之蚤定也，其應敵也周，其總率也極。","zh-Hant"]]},{"id":"wei-liao-zi_ch-5_p-9_s-3","passageId":"wei-liao-zi_ch-5_p-9","order":3,"canonicalText":"故五人而伍，十人而什，百人而卒，萬人而將，此之謂法制之師。","chunks":[["故五人而伍，十人而什，百人而卒，千人而率，萬人而將，已周已極，其朝死則朝代，暮死則暮代，權敵審將，而後舉兵。","zh-Hant"]]},{"id":"wei-liao-zi_ch-1_p-1_s-1","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-1","order":1,"canonicalText":"梁惠王問尉繚子曰：「黃帝刑德，可以百勝，有之乎？","chunks":[]},{"id":"wei-liao-zi_ch-1_p-1_s-2","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-1","order":2,"canonicalText":"」尉繚子對曰：「刑以伐之，德以守之，非所謂天官時日陰陽向背也。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-1_s-3","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-1","order":3,"canonicalText":"黃帝者，人事而已矣。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-1_s-4","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-1","order":4,"canonicalText":"何者？","chunks":[]},{"id":"wei-liao-zi_ch-1_p-1_s-5","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-1","order":5,"canonicalText":"今高城深池，宿儲不備，卒雖百萬，何以能守？","chunks":[]},{"id":"wei-liao-zi_ch-1_p-1_s-6","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-1","order":6,"canonicalText":"」","chunks":[]},{"id":"wei-liao-zi_ch-1_p-3_s-1","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-3","order":1,"canonicalText":"「按天官曰：『背水陣為絕地，向阪陣為廢軍。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-3_s-2","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-3","order":2,"canonicalText":"』武王伐紂，背濟水向山阪而陣，以二萬二千五百人，擊紂之億萬之眾，而破商紂。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-3_s-3","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-3","order":3,"canonicalText":"豈紂不得吉日，而武王反得兇時乎？","chunks":[]},{"id":"wei-liao-zi_ch-1_p-3_s-4","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-3","order":4,"canonicalText":"非也，政審而兵精也。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-3_s-5","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-3","order":5,"canonicalText":"」","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-1","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":1,"canonicalText":"「楚將公子心與齊人戰，時有彗星出，柄在齊。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-2","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":2,"canonicalText":"柄所在勝，不可擊。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-3","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":3,"canonicalText":"公子心曰：『彗星何知？","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-4","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":4,"canonicalText":"以彗鬥者，固當倒而擊之。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-5","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":5,"canonicalText":"』明日與齊戰，大破齊軍。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-6","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":6,"canonicalText":"故勝在人，不在天也。","chunks":[]},{"id":"wei-liao-zi_ch-1_p-4_s-7","chapterId":"wei-liao-zi_ch-1","passageId":"wei-liao-zi_ch-1_p-4","order":7,"canonicalText":"」","chunks":[]},{"id":"wei-liao-zi_ch-2_p-2_s-1","chapterId":"wei-liao-zi_ch-2","passageId":"wei-liao-zi_ch-2_p-2","order":1,"canonicalText":"治兵者，若祕於地，若邃於天，生於無，故關之。","chunks":[]},{"id":"wei-liao-zi_ch-2_p-2_s-2","chapterId":"wei-liao-zi_ch-2","passageId":"wei-liao-zi_ch-2_p-2","order":2,"canonicalText":"大不窕，小不恢，明乎禁舍開塞，民流者親之。","chunks":[]},{"id":"wei-liao-zi_ch-2_p-2_s-3","chapterId":"wei-liao-zi_ch-2","passageId":"wei-liao-zi_ch-2_p-2","order":3,"canonicalText":"地不闢，田不荒，兵強而國富，此治兵之本也。","chunks":[]},{"id":"wei-liao-zi_ch-2_p-4_s-1","chapterId":"wei-liao-zi_ch-2","passageId":"wei-liao-zi_ch-2_p-4","order":1,"canonicalText":"將者，上不制於天，下不制於地，中不制於人，寬不可激而怒，清不可事以財。","chunks":[]},{"id":"wei-liao-zi_ch-2_p-4_s-2","chapterId":"wei-liao-zi_ch-2","passageId":"wei-liao-zi_ch-2_p-4","order":2,"canonicalText":"夫心狂、目盲、耳聾，不可為將也。","chunks":[]},{"id":"wei-liao-zi_ch-2_p-4_s-3","chapterId":"wei-liao-zi_ch-2","passageId":"wei-liao-zi_ch-2_p-4","order":3,"canonicalText":"將明則三軍附，將威則三軍整。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-2_s-1","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-2","order":1,"canonicalText":"古者，士有什伍，車有偏列，鼓鳴旂麾，先登者未嘗非多力國士也，先死者亦未嘗非多力國士也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-2_s-2","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-2","order":2,"canonicalText":"故賞其勇，罰其怯，明其分，使人皆知所趨舍。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-3_s-1","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-3","order":1,"canonicalText":"損敵一人，而損我百人，此資敵而傷甚焉，世將不能禁。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-3_s-2","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-3","order":2,"canonicalText":"徵役分軍而逃歸，或臨戰自北，則逃傷甚焉，故立法以禁之。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-6_s-1","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-6","order":1,"canonicalText":"一賊仗劍擊於市，萬人無不避之者，臣謂：『非一人之獨勇，萬人皆不肖也』。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-6_s-2","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-6","order":2,"canonicalText":"何則？","chunks":[]},{"id":"wei-liao-zi_ch-3_p-6_s-3","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-6","order":3,"canonicalText":"『必死與必生，形不相接也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-6_s-4","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-6","order":4,"canonicalText":"』故治軍者，在使士卒致必死之志也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-1","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":1,"canonicalText":"有提九萬之眾，而天下莫能當者，誰？","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-2","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":2,"canonicalText":"曰：『桓公也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-3","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":3,"canonicalText":"』有提七萬之眾，而天下莫敢當者，誰？","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-4","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":4,"canonicalText":"曰：『吳起也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-5","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":5,"canonicalText":"』有提三萬之眾，而天下莫敢當者，誰？","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-6","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":6,"canonicalText":"曰：『武王也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-7_s-7","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-7","order":7,"canonicalText":"』兵在精而不在多也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-10_s-1","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-10","order":1,"canonicalText":"吾用天下之用為用，吾制天下之制為制，修吾號令，明吾刑賞，使天下非農所得食，非戰無所得爵，使民樂耕而勇戰，則天下無敵矣。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-11_s-1","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-11","order":1,"canonicalText":"民言有可以勝敵者，毋許其空言，必試其能戰也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-11_s-2","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-11","order":2,"canonicalText":"策士以舌辯得官，而戰士以血肉膏野，此國之所以亂也。","chunks":[]},{"id":"wei-liao-zi_ch-3_p-11_s-3","chapterId":"wei-liao-zi_ch-3","passageId":"wei-liao-zi_ch-3_p-11","order":3,"canonicalText":"故求實功，斥浮偽，天下可定。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-2_s-1","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-2","order":1,"canonicalText":"夫將之所以戰者民也，民之所以戰者氣也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-2_s-2","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-2","order":2,"canonicalText":"氣實則鬥，氣奪則走。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-2_s-3","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-2","order":3,"canonicalText":"故善戰者，必先養其氣，奪敵之氣，然後戰可勝也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-4_s-1","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-4","order":1,"canonicalText":"善用兵者，能奪人而不奪於人。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-4_s-2","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-4","order":2,"canonicalText":"奪者心之機也，令者一眾心也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-4_s-3","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-4","order":3,"canonicalText":"眾不審則數變，數變則令雖出眾不信矣。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-4_s-4","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-4","order":4,"canonicalText":"故令出如山，不可反也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-7_s-1","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-7","order":1,"canonicalText":"故戰者必本乎率身以勵眾士，如心之使四肢也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-7_s-2","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-7","order":2,"canonicalText":"志不勵則士不死節，士不死節則眾不戰。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-7_s-3","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-7","order":3,"canonicalText":"將帥以身先之，則三軍爭勇矣。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-12_s-1","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-12","order":1,"canonicalText":"夫以居攻出，則居欲重，陣欲堅，發欲畢，鬥欲齊。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-12_s-2","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-12","order":2,"canonicalText":"因敵制變，乘勢以決之。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-13_s-1","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-13","order":1,"canonicalText":"王國富民，伯國富士，謹存之國富大夫，亡國富食府。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-13_s-2","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-13","order":2,"canonicalText":"所謂上滿下漏，患無所救。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-13_s-3","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-13","order":3,"canonicalText":"故富國之道，在於富民也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-1","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":1,"canonicalText":"故曰：『舉賢任能，不時日而事利；","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-2","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":2,"canonicalText":"明法審令，不卜筮而事吉；","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-3","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":3,"canonicalText":"貴功養勞，不禱祠而得福。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-4","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":4,"canonicalText":"』又曰：『兵者，兇器也；","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-5","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":5,"canonicalText":"爭者，逆德也；","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-6","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":6,"canonicalText":"事必有本，不可以末治本也。","chunks":[]},{"id":"wei-liao-zi_ch-4_p-14_s-7","chapterId":"wei-liao-zi_ch-4","passageId":"wei-liao-zi_ch-4_p-14","order":7,"canonicalText":"』","chunks":[]},{"id":"wei-liao-zi_ch-5_p-8_s-1","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-8","order":1,"canonicalText":"兵有勝於朝廷，有勝於原野，有勝於市井，鬥則得，服則失，幸以不敗，此不意彼驚懼而曲勝之也。","chunks":[]},{"id":"wei-liao-zi_ch-5_p-8_s-2","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-8","order":2,"canonicalText":"曲勝非全勝也，全勝者，攻其所必救，擊其所不備也。","chunks":[]},{"id":"wei-liao-zi_ch-5_p-10_s-1","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-10","order":1,"canonicalText":"故凡集兵千里者旬日，百里者一日，必集敵境。","chunks":[]},{"id":"wei-liao-zi_ch-5_p-10_s-2","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-10","order":2,"canonicalText":"卒聚將至，深入其地，錯絕其道，棲其大城大邑，使之進不得戰，退不得守，此破國之術也。","chunks":[]},{"id":"wei-liao-zi_ch-5_p-11_s-1","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-11","order":1,"canonicalText":"津樑未發，要塞未修，城險未設，渠答未張，則雖有城無守矣。","chunks":[]},{"id":"wei-liao-zi_ch-5_p-11_s-2","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-11","order":2,"canonicalText":"遠堡未入，戍客未歸，則雖有人無人矣。","chunks":[]},{"id":"wei-liao-zi_ch-5_p-11_s-3","chapterId":"wei-liao-zi_ch-5","passageId":"wei-liao-zi_ch-5_p-11","order":3,"canonicalText":"故善守者，必先備於未形，此守國之要也。","chunks":[]}]}');export{i as default};
